const moneyFormatter = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});

function formatMoney(value: number) {
  return moneyFormatter.format(value);
}

function formatFileSize(bytes: number | null | undefined) {
  if (!bytes || bytes <= 0) {
    return "Size pending";
  }

  const units = ["B", "KB", "MB", "GB"];
  let value = bytes;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }

  return `${value >= 10 || unitIndex === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
}

function getFormString(formData: FormData, key: string, fallback = "") {
  const value = formData.get(key);
  return typeof value === "string" && value.trim() ? value.trim() : fallback;
}

function getOptionalFormString(formData: FormData, key: string) {
  const value = getFormString(formData, key);
  return value || null;
}

function normalizeCrmTextInput(value: string | null | undefined) {
  return (value ?? "").trim().replace(/\s+/g, " ");
}

function getNormalizedFormString(formData: FormData, key: string, fallback = "") {
  const value = formData.get(key);
  const normalized = typeof value === "string" ? normalizeCrmTextInput(value) : "";

  return normalized || fallback;
}

function getNormalizedOptionalFormString(formData: FormData, key: string) {
  const value = getNormalizedFormString(formData, key);
  return value || null;
}

function getNormalizedEmailFormString(formData: FormData, key: string) {
  const value = getNormalizedFormString(formData, key);

  if (!value) {
    return null;
  }

  return normalizeLeadIntakeEmail(value) ?? value.toLowerCase();
}

function getNormalizedPhoneFormString(formData: FormData, key: string) {
  const value = getNormalizedFormString(formData, key);

  return value ? normalizeLeadIntakePhone(value) ?? value : null;
}

function isValidOptionalEmail(value: string | null | undefined) {
  return !value || normalizeLeadIntakeEmail(value) !== null;
}

function getOptionalRelation(formData: FormData, key: string) {
  const value = getFormString(formData, key);
  return value && value !== "none" ? value : null;
}

function getOptionalFormFile(formData: FormData, key: string) {
  const value = formData.get(key);
  return value instanceof File && value.size > 0 ? value : null;
}

function getFormNumber(formData: FormData, key: string) {
  const value = getFormString(formData, key).replace(/[^0-9.]/g, "");
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function getOptionalFiniteFinancialFormNumber(
  formData: FormData,
  key: string,
): number | undefined {
  const parsed = parseFiniteFinancialInput(formData.get(key));
  if (parsed.status === "empty") {
    return undefined;
  }

  return parsed.status === "valid" ? parsed.value : Number.NaN;
}

function companyInitials(company: CompanyRecord | null | undefined) {
  if (!company) {
    return "OS";
  }

  return company.name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}

function getCompanyBrandColor(company: CompanyRecord | null | undefined) {
  if (company && isPaintingCompany(company)) {
    return "var(--wt-painting-orange)";
  }

  if (
    !company ||
    company.trade === "roofing" ||
    company.workflow_profile === "roofing"
  ) {
    return "var(--wt-roofing-purple)";
  }

  const brandColor = company?.brand_color?.toLowerCase();

  if (!brandColor || brandColor === "#0284c7" || brandColor === "#0ea5e9") {
    return "var(--wt-roofing-purple)";
  }

  return company.brand_color ?? "var(--wt-roofing-purple)";
}

function companyTradeLabel(company: CompanyRecord | null | undefined) {
  if (!company) {
    return "All-company workspace";
  }

  return `${company.trade === "both" ? "Shared" : company.trade} workflow`;
}

function statusLabel(status: LeadStatus) {
  return leadStatuses.find((item) => item.value === status)?.label ?? status;
}

function pipelineStageLabel(stage: PipelineStage) {
  return pipelineStages.find((item) => item.value === stage)?.label ?? stage;
}

function leadStatusForPipelineStage(stage: PipelineStage): LeadStatus {
  if (stage === "new_lead") {
    return "new";
  }

  if (stage === "estimate_scheduled") {
    return "qualified";
  }

  if (
    stage === "approved" ||
    stage === "job_scheduled" ||
    stage === "completed" ||
    stage === "paid"
  ) {
    return "estimate_sent";
  }

  return stage;
}

function getLeadPipelineStageFromForm(formData: FormData) {
  const value = getNormalizedFormString(formData, "pipeline_stage", "new_lead");

  return pipelineStages.some((stage) => stage.value === value)
    ? (value as PipelineStage)
    : "new_lead";
}

type ManualLeadInput = LeadInput & {
  source_detail?: string | null;
  campaign_id?: string | null;
};

function normalizeAttributionSlug(value: string | null) {
  const slug = value
    ?.trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return slug || null;
}

function buildLeadInputFromFormData(
  formData: FormData,
  companies: CompanyRecord[],
): ManualLeadInput {
  const pipelineStage = getLeadPipelineStageFromForm(formData);

  return {
    company_id: getNormalizedFormString(formData, "company_id", companies[0]?.id),
    contact_name: getNormalizedFormString(formData, "contact_name"),
    phone: getNormalizedPhoneFormString(formData, "phone"),
    email: getNormalizedEmailFormString(formData, "email"),
    property_address: getNormalizedFormString(formData, "property_address"),
    city: getNormalizedOptionalFormString(formData, "city"),
    state: getNormalizedFormString(formData, "state", "AZ"),
    postal_code: getNormalizedOptionalFormString(formData, "postal_code"),
    service_type: getNormalizedFormString(formData, "service_type", "roofing") as ServiceType,
    source: getNormalizedFormString(formData, "source", "unknown"),
    source_detail: normalizeAttributionSlug(
      getNormalizedOptionalFormString(formData, "source_detail"),
    ),
    campaign_id: getNormalizedOptionalFormString(formData, "campaign_id"),
    status: leadStatusForPipelineStage(pipelineStage),
    pipeline_stage: pipelineStage,
    priority: getNormalizedFormString(formData, "priority", "normal") as LeadPriority,
    estimated_value: getOptionalFiniteFinancialFormNumber(
      formData,
      "estimated_value",
    ),
    next_follow_up: getNormalizedOptionalFormString(formData, "next_follow_up"),
    notes: getNormalizedOptionalFormString(formData, "notes"),
  } satisfies ManualLeadInput;
}

function buildCreateAccountableLeadRequest(
  input: ManualLeadInput,
  operationKey = crypto.randomUUID(),
): CreateAccountableLeadRequest {
  const requestedSource = canonicalAttributionSourceKeys.includes(
    input.source as AttributionSourceKey,
  )
    ? (input.source as AttributionSourceKey)
    : "unknown";
  if (requestedSource === "repeat_customer") {
    throw new Error(
      "Repeat-customer attribution can only be created from the same-company Customer 360 workflow.",
    );
  }
  const attribution = resolveLeadAcquisitionAttribution({
    explicitSourceKey: requestedSource,
    explicitSourceDetail: input.source_detail,
    explicitUnknown: requestedSource === "unknown",
    intakeProvider: "manual",
  });

  return {
    operation_key: operationKey,
    company_id: input.company_id,
    contact_name: input.contact_name,
    phone: input.phone ?? null,
    email: input.email ?? null,
    property_address: input.property_address,
    city: input.city ?? null,
    state: input.state ?? "AZ",
    postal_code: input.postal_code ?? null,
    service_type: input.service_type,
    priority: input.priority ?? "normal",
    ...(input.estimated_value !== undefined
      ? { estimated_value: input.estimated_value }
      : {}),
    next_follow_up: input.next_follow_up ?? null,
    notes: input.notes ?? null,
    source_key: attribution.sourceKey,
    source_detail: attribution.sourceDetail,
    intake_provider: "manual",
    campaign_id: input.campaign_id ?? null,
    evidence_kind: attribution.evidenceKind,
    review_status: attribution.reviewStatus,
  };
}

function createDemoLeadAccountability(
  lead: LeadRecord,
  sourceKey: AttributionSourceKey,
  evidenceKind: AttributionEvidenceKind,
  reviewStatus: AttributionReviewStatus,
  attribution?: Pick<
    CreateAccountableLeadRequest,
    "source_detail" | "intake_provider" | "campaign_id" | "intake_record_id"
  >,
  requestedOperationKey?: string,
): {
  accountability: LeadAccountabilityRecord;
  event: LeadAccountabilityEventRecord;
} {
  const createdAt = lead.created_at;
  const accountabilityId = `demo-accountability-${lead.id}`;
  const operationKey = requestedOperationKey ?? `demo-create:${lead.id}`;
  const accountability: LeadAccountabilityRecord = {
    id: accountabilityId,
    company_id: lead.company_id,
    lead_id: lead.id,
    source_key: sourceKey,
    source_detail: attribution?.source_detail ?? null,
    intake_provider: attribution?.intake_provider ?? "manual",
    campaign_id: attribution?.campaign_id ?? null,
    intake_record_id: attribution?.intake_record_id ?? null,
    attribution_model: "first_touch",
    received_at: createdAt,
    evidence_kind: evidenceKind,
    review_status: reviewStatus,
    reviewed_by: null,
    reviewed_at: null,
    attribution_locked_at: reviewStatus === "verified" ? createdAt : null,
    owner_user_id: null,
    owner_assigned_at: null,
    first_response_at: null,
    first_response_channel: null,
    outcome: "open",
    outcome_at: null,
    lost_reason_code: null,
    lost_reason_notes: null,
    won_contract_value: null,
    won_value_basis: null,
    record_version: 1,
    last_operation_key: operationKey,
    last_request_fingerprint: operationKey,
    created_at: createdAt,
    updated_at: createdAt,
  };

  return {
    accountability,
    event: {
      id: `demo-accountability-event-${lead.id}`,
      lead_accountability_id: accountabilityId,
      company_id: lead.company_id,
      lead_id: lead.id,
      event_type: "lead_created",
      operation_key: operationKey,
      request_fingerprint: operationKey,
      actor_user_id: null,
      actor_kind: "user",
      reason_code: null,
      source_key: sourceKey,
      source_detail: attribution?.source_detail ?? null,
      intake_provider: accountability.intake_provider,
      campaign_id: attribution?.campaign_id ?? null,
      owner_user_id: null,
      first_response_channel: null,
      linked_table: "leads",
      linked_record_id: lead.id,
      outcome: "open",
      lost_reason_code: null,
      won_contract_value: null,
      won_value_basis: null,
      occurred_at: createdAt,
      resulting_record_version: 1,
      created_at: createdAt,
    },
  };
}

function createDemoLeadRecord(input: LeadInput): LeadRecord {
  const now = new Date().toISOString();

  return {
    id: `demo-lead-${Date.now()}`,
    company_id: input.company_id,
    customer_id: null,
    contact_name: input.contact_name,
    phone: input.phone ?? null,
    email: input.email ?? null,
    property_address: input.property_address,
    city: input.city ?? null,
    state: input.state ?? "AZ",
    postal_code: input.postal_code ?? null,
    latitude: input.latitude ?? null,
    longitude: input.longitude ?? null,
    google_place_id: input.google_place_id ?? null,
    address_verified_at: input.address_verified_at ?? null,
    service_type: input.service_type,
    source: input.source ?? "unknown",
    status: input.status ?? "new",
    pipeline_stage: input.pipeline_stage ?? "new_lead",
    priority: input.priority ?? "normal",
    estimated_value: input.estimated_value ?? 0,
    next_follow_up: input.next_follow_up ?? null,
    notes: input.notes ?? null,
    created_by: null,
    created_at: now,
    updated_at: now,
  };
}

function projectDemoAccountabilityMilestones(
  previous: CrmSnapshot,
  next: CrmSnapshot,
): CrmSnapshot {
  let accountability = [...next.leadAccountability];
  let events = [...next.leadAccountabilityEvents];
  let leads = [...next.leads];

  const appendMilestone = ({
    companyId,
    leadId,
    eventType,
    linkedTable,
    linkedRecordId,
    occurredAt,
    wonContractValue = null,
    wonValueBasis = null,
  }: {
    companyId: string;
    leadId: string;
    eventType: Extract<
      LeadAccountabilityEventRecord["event_type"],
      "appointment_scheduled" | "inspection_completed" | "estimate_sent" | "won"
    >;
    linkedTable: string;
    linkedRecordId: string;
    occurredAt: string;
    wonContractValue?: number | null;
    wonValueBasis?: LeadAccountabilityEventRecord["won_value_basis"];
  }) => {
    const recordIndex = accountability.findIndex(
      (record) =>
        record.company_id === companyId && record.lead_id === leadId,
    );
    if (recordIndex < 0) {
      return;
    }
    const current = accountability[recordIndex];
    const operationKey = `demo-workflow:${linkedTable}:${linkedRecordId}:${eventType}`;
    if (
      events.some(
        (event) =>
          event.company_id === companyId && event.operation_key === operationKey,
      )
    ) {
      return;
    }
    const preflightError = getAccountabilityActionPreflightError({
      action: eventType,
      outcome: current.outcome,
      firstResponseAt: current.first_response_at,
      occurredAt,
      events: events
        .filter((event) => event.lead_accountability_id === current.id)
        .map((event) => ({
          eventType: event.event_type,
          occurredAt: event.occurred_at,
        })),
    });
    if (preflightError) {
      return;
    }

    const nextVersion = current.record_version + 1;
    const updated: LeadAccountabilityRecord = {
      ...current,
      ...(eventType === "won"
        ? {
            outcome: "won" as const,
            outcome_at: occurredAt,
            won_contract_value: wonContractValue,
            won_value_basis: wonValueBasis,
          }
        : {}),
      record_version: nextVersion,
      last_operation_key: operationKey,
      last_request_fingerprint: operationKey,
      updated_at: occurredAt,
    };
    accountability[recordIndex] = updated;
    events = [
      {
        id: `demo-accountability-event-${crypto.randomUUID()}`,
        lead_accountability_id: current.id,
        company_id: companyId,
        lead_id: leadId,
        event_type: eventType,
        operation_key: operationKey,
        request_fingerprint: operationKey,
        actor_user_id: null,
        actor_kind: "system",
        reason_code: null,
        source_key: updated.source_key,
        source_detail: updated.source_detail,
        intake_provider: updated.intake_provider,
        campaign_id: updated.campaign_id,
        owner_user_id: null,
        first_response_channel: null,
        linked_table: linkedTable,
        linked_record_id: linkedRecordId,
        outcome: eventType === "won" ? "won" : null,
        lost_reason_code: null,
        won_contract_value: eventType === "won" ? wonContractValue : null,
        won_value_basis: eventType === "won" ? wonValueBasis : null,
        occurred_at: occurredAt,
        resulting_record_version: nextVersion,
        created_at: occurredAt,
      },
      ...events,
    ];
    leads = leads.map((lead) => {
      if (lead.id !== leadId || lead.company_id !== companyId) {
        return lead;
      }
      if (eventType === "won") {
        return { ...lead, status: "won", pipeline_stage: "approved", updated_at: occurredAt };
      }
      if (eventType === "estimate_sent") {
        return {
          ...lead,
          status: ["new", "contacted", "qualified"].includes(lead.status)
            ? "estimate_sent"
            : lead.status,
          pipeline_stage: ["new_lead", "contacted", "estimate_scheduled"].includes(
            lead.pipeline_stage,
          )
            ? "estimate_sent"
            : lead.pipeline_stage,
          updated_at: occurredAt,
        };
      }
      return {
        ...lead,
        status: lead.status === "new" || lead.status === "contacted" ? "qualified" : lead.status,
        pipeline_stage:
          lead.pipeline_stage === "new_lead" || lead.pipeline_stage === "contacted"
            ? "estimate_scheduled"
            : lead.pipeline_stage,
        updated_at: occurredAt,
      };
    });
  };

  const scheduleChanged = (record: ScheduleEventRecord) => {
    const prior = previous.scheduleEvents.find((item) => item.id === record.id);
    return (
      !prior ||
      prior.updated_at !== record.updated_at ||
      prior.status !== record.status ||
      prior.start_at !== record.start_at
    );
  };
  next.scheduleEvents
    .filter(
      (record) =>
        scheduleChanged(record) &&
        Boolean(record.lead_id) &&
        (record.event_type === "inspection" || record.event_type === "estimate") &&
        (record.status === "scheduled" || record.status === "completed"),
    )
    .forEach((record) =>
      appendMilestone({
        companyId: record.company_id,
        leadId: record.lead_id as string,
        eventType: "appointment_scheduled",
        linkedTable: "schedule_events",
        linkedRecordId: record.id,
        occurredAt: record.created_at,
      }),
    );

  next.inspections
    .filter((record) => {
      const prior = previous.inspections.find((item) => item.id === record.id);
      return (
        (!prior ||
          prior.updated_at !== record.updated_at ||
          prior.status !== record.status ||
          prior.completed_at !== record.completed_at) &&
        (record.completed_at !== null ||
          ["completed", "passed", "failed", "no_work_needed"].includes(record.status))
      );
    })
    .forEach((record) => {
      const estimateLeadId = record.estimate_id
        ? next.estimates.find(
            (estimate) =>
              estimate.id === record.estimate_id &&
              estimate.company_id === record.company_id,
          )?.lead_id
        : null;
      const jobLeadId = record.job_id
        ? next.jobs.find(
            (job) => job.id === record.job_id && job.company_id === record.company_id,
          )?.lead_id
        : null;
      const leadId = record.lead_id ?? estimateLeadId ?? jobLeadId;
      if (leadId) {
        appendMilestone({
          companyId: record.company_id,
          leadId,
          eventType: "inspection_completed",
          linkedTable: "inspections",
          linkedRecordId: record.id,
          occurredAt: record.completed_at ?? record.updated_at,
        });
      }
    });

  next.estimates
    .filter((record) => {
      const prior = previous.estimates.find((item) => item.id === record.id);
      return (
        Boolean(record.lead_id) &&
        record.status === "sent" &&
        (!prior || prior.status !== record.status || prior.updated_at !== record.updated_at)
      );
    })
    .forEach((record) =>
      appendMilestone({
        companyId: record.company_id,
        leadId: record.lead_id as string,
        eventType: "estimate_sent",
        linkedTable: "estimates",
        linkedRecordId: record.id,
        occurredAt: record.updated_at,
      }),
    );

  next.proposalAcceptances
    .filter((record) => {
      const prior = previous.proposalAcceptances.find((item) => item.id === record.id);
      return (
        record.terms_accepted &&
        record.accepted_total > 0 &&
        (record.acceptance_method !== "signature_provider" ||
          record.signature_status === "signed") &&
        (!prior ||
          prior.accepted_at !== record.accepted_at ||
          prior.signature_status !== record.signature_status)
      );
    })
    .forEach((record) => {
      const estimate = next.estimates.find(
        (item) =>
          item.id === record.estimate_id && item.company_id === record.company_id,
      );
      if (estimate?.lead_id) {
        appendMilestone({
          companyId: record.company_id,
          leadId: estimate.lead_id,
          eventType: "won",
          linkedTable: "estimate_proposal_acceptances",
          linkedRecordId: record.id,
          occurredAt: record.accepted_at,
          wonContractValue: record.accepted_total,
          wonValueBasis:
            record.signature_status === "signed"
              ? "signed_proposal"
              : "accepted_proposal",
        });
      }
    });

  return { ...next, leads, leadAccountability: accountability, leadAccountabilityEvents: events };
}

function customerStatusLabel(status: CustomerStatus) {
  return customerStatuses.find((item) => item.value === status)?.label ?? status;
}

function customerTypeLabel(type: CustomerType) {
  return customerTypes.find((item) => item.value === type)?.label ?? type;
}

function estimateStatusLabel(status: EstimateStatus) {
  return estimateStatuses.find((item) => item.value === status)?.label ?? status;
}

function getEstimateTimelineUpdateLabel(status: EstimateStatus) {
  if (status === "sent") {
    return "Estimate sent";
  }

  if (status === "approved") {
    return "Estimate approved";
  }

  if (status === "declined" || status === "rejected") {
    return "Estimate rejected";
  }

  if (status === "expired") {
    return "Estimate expired";
  }

  return "Estimate revised";
}

function getEstimateTimelineTone(status: EstimateStatus): CustomerTimelineItem["tone"] {
  if (status === "approved") {
    return "green";
  }

  if (status === "declined" || status === "rejected" || status === "expired") {
    return "amber";
  }

  return "blue";
}

function getEstimateHandoffAddress(
  snapshot: CrmSnapshot,
  estimate: EstimateRecord,
) {
  const customer = estimate.customer_id
    ? snapshot.customers.find((item) => item.id === estimate.customer_id)
    : null;
  const lead = estimate.lead_id
    ? snapshot.leads.find((item) => item.id === estimate.lead_id)
    : null;

  return (
    estimate.location?.trim() ||
    customer?.property_address ||
    lead?.property_address ||
    null
  );
}

function findPotentialEstimateJob(
  snapshot: CrmSnapshot,
  estimate: EstimateRecord,
) {
  const candidates = snapshot.jobs.filter((job) => {
      if (
        job.company_id !== estimate.company_id ||
        (job.estimate_id !== null && job.estimate_id !== estimate.id) ||
        job.status !== "draft" ||
        job.proposal_revision_id !== null ||
        job.proposal_acceptance_id !== null ||
        job.conversion_operation_key !== null
      ) {
        return false;
      }

      const conflictingCustomer = Boolean(
        job.customer_id && job.customer_id !== estimate.customer_id,
      );
      const conflictingLead = Boolean(job.lead_id && job.lead_id !== estimate.lead_id);
      const conflictingProperty = Boolean(
        job.property_id && job.property_id !== estimate.property_id,
      );

      if (conflictingCustomer || conflictingLead || conflictingProperty) {
        return false;
      }

      if (job.estimate_id === estimate.id) {
        return true;
      }

      const allAvailableIdentitiesMatch = [
        !estimate.customer_id || job.customer_id === estimate.customer_id,
        !estimate.lead_id || job.lead_id === estimate.lead_id,
        !estimate.property_id || job.property_id === estimate.property_id,
      ].every(Boolean);
      const hasStableIdentity = Boolean(
        estimate.customer_id || estimate.lead_id || estimate.property_id,
      );
      const normalizedEstimateTitle = estimate.title.trim().toLowerCase();
      const normalizedEstimateAddress = getEstimateHandoffAddress(
        snapshot,
        estimate,
      )
        ?.trim()
        .toLowerCase();
      const normalizedJobAddresses = [
        job.address,
        job.property_address,
        job.location,
      ]
        .map((value) => value?.trim().toLowerCase())
        .filter(Boolean);
      const projectIdentityMatches = Boolean(
        (normalizedEstimateTitle &&
          job.title.trim().toLowerCase() === normalizedEstimateTitle) ||
          (normalizedEstimateAddress &&
            normalizedJobAddresses.includes(normalizedEstimateAddress)),
      );

      return (
        job.service_type === estimate.service_type &&
        hasStableIdentity &&
        allAvailableIdentitiesMatch &&
        projectIdentityMatches
      );
    });

  const exactEstimateCandidates = candidates.filter(
    (job) => job.estimate_id === estimate.id,
  );
  const preferredCandidates = exactEstimateCandidates.length
    ? exactEstimateCandidates
    : candidates.filter((job) => job.estimate_id === null);

  return preferredCandidates.length === 1 ? preferredCandidates[0] : null;
}

function findExactProposalSoldJob(
  snapshot: CrmSnapshot,
  estimate: EstimateRecord,
  proposalRevisionId: string | null,
  acceptanceId: string | null,
) {
  if (!proposalRevisionId || !acceptanceId) {
    return null;
  }

  return (
    snapshot.jobs.find(
      (job) =>
        job.company_id === estimate.company_id &&
        job.customer_id === estimate.customer_id &&
        job.estimate_id === estimate.id &&
        job.proposal_revision_id === proposalRevisionId &&
        job.proposal_acceptance_id === acceptanceId &&
        job.conversion_operation_key === acceptanceId,
    ) ?? null
  );
}

function getEstimateRelatedInspection(
  snapshot: CrmSnapshot,
  estimate: EstimateRecord,
  linkedJob: JobRecord | null,
) {
  return (
    snapshot.inspections.find((inspection) => inspection.estimate_id === estimate.id) ??
    snapshot.inspections.find(
      (inspection) => linkedJob && inspection.job_id === linkedJob.id,
    ) ??
    snapshot.inspections.find(
      (inspection) =>
        inspection.company_id === estimate.company_id &&
        ((estimate.customer_id !== null &&
          inspection.customer_id === estimate.customer_id) ||
          (estimate.lead_id !== null && inspection.lead_id === estimate.lead_id)),
    ) ??
    null
  );
}

function getEstimateRelatedPhotos(
  snapshot: CrmSnapshot,
  estimate: EstimateRecord,
  linkedJob: JobRecord | null,
  linkedInspection: InspectionRecord | null,
) {
  const exactPhotos = snapshot.jobPhotos.filter(
    (photo) =>
      photo.estimate_id === estimate.id ||
      (linkedJob !== null && photo.job_id === linkedJob.id) ||
      (linkedInspection !== null && photo.inspection_id === linkedInspection.id),
  );

  if (exactPhotos.length > 0) {
    return exactPhotos;
  }

  return snapshot.jobPhotos.filter(
    (photo) =>
      estimate.customer_id !== null &&
      photo.customer_id === estimate.customer_id &&
      photo.company_id === estimate.company_id,
  );
}

