const fieldIssueTypes = [
  "Customer unavailable",
  "Access issue",
  "Hidden damage",
  "Additional work discovered",
  "Material shortage",
  "Weather delay",
  "Safety concern",
  "Inspection required",
  "Change order needed",
];

function fieldReadinessTone(state: FieldReadinessState): "blue" | "green" | "amber" {
  if (state === "Ready") {
    return "green";
  }

  if (state === "Not Tracked") {
    return "blue";
  }

  return "amber";
}

function getFieldTradeTerms(job: JobRecord, company: CompanyRecord | null) {
  const isPaintingJob =
    job.service_type === "painting" || Boolean(company && isPaintingCompany(company));

  return isPaintingJob
    ? [
        "Power washing",
        "Masking",
        "Surface preparation",
        "Stucco repair",
        "Color approval",
        "Painting progress",
        "Cleanup",
        "Final paint walkthrough",
      ]
    : [
        "Tear-off",
        "Tile reset",
        "Underlayment",
        "Flashing",
        "Dry-in",
        "Foam or coating",
        "Leak repair",
        "Final roof walkthrough",
      ];
}

function buildFieldWorkBuckets(snapshot: CrmSnapshot): FieldWorkBucket[] {
  const today = todayIsoDate();
  const upcomingEnd = addDaysToIsoDate(today, 7);
  const activeJobs = snapshot.jobs.filter(isProductionActiveJob);
  const scheduledToday = activeJobs.filter((job) =>
    getJobScheduleDateParts(snapshot, job).some((date) => date === today),
  );
  const upcomingAssigned = activeJobs.filter((job) => {
    const dates = getJobScheduleDateParts(snapshot, job);

    return (
      jobHasCrew(snapshot, job) &&
      dates.some((date) => date > today && date <= upcomingEnd)
    );
  });
  const waitingOnCustomer = activeJobs.filter((job) => {
    const text = jobProductionText(job);

    return (
      job.status === "blocked" &&
      (text.includes("customer") ||
        text.includes("approval") ||
        text.includes("hoa") ||
        getJobChangeOrders(snapshot, job.id).some(
          (changeOrder) => changeOrder.status === "sent",
        ))
    );
  });
  const waitingOnMaterials = activeJobs.filter((job) => {
    const readiness = getJobMaterialReadiness(snapshot, job);

    return ["Request Needed", "Requested", "Ordered", "Partial", "Delayed"].includes(
      readiness.label,
    );
  });
  const finalWalkthrough = activeJobs.filter((job) => jobNeedsFinalWalkthrough(snapshot, job));
  const warranty = snapshot.jobs.filter((job) => jobHasWarrantySignal(snapshot, job));

  return [
    {
      id: "assigned-today",
      label: "Assigned today",
      detail: "Scheduled jobs with current production dates",
      jobs: scheduledToday,
      tone: scheduledToday.length ? "blue" : "green",
      icon: CalendarClock,
    },
    {
      id: "upcoming-assigned",
      label: "Upcoming assigned",
      detail: "Crew-tracked jobs in the next seven days",
      jobs: upcomingAssigned,
      tone: upcomingAssigned.length ? "blue" : "green",
      icon: Users,
    },
    {
      id: "in-progress",
      label: "In progress",
      detail: "Jobs currently marked in production",
      jobs: snapshot.jobs.filter((job) => job.status === "in_progress"),
      tone: "blue",
      icon: Activity,
    },
    {
      id: "waiting-customer",
      label: "Waiting on customer",
      detail: "Blocked by customer, HOA, or approval signals",
      jobs: waitingOnCustomer,
      tone: waitingOnCustomer.length ? "amber" : "green",
      icon: UserRound,
    },
    {
      id: "waiting-materials",
      label: "Waiting on materials",
      detail: "Material readiness needs office review",
      jobs: waitingOnMaterials,
      tone: waitingOnMaterials.length ? "amber" : "green",
      icon: Package,
    },
    {
      id: "final-walkthrough",
      label: "Needs final walkthrough",
      detail: "Checklist complete while the job is still open",
      jobs: finalWalkthrough,
      tone: finalWalkthrough.length ? "amber" : "green",
      icon: CheckCircle2,
    },
    {
      id: "warranty-callbacks",
      label: "Warranty or callback",
      detail: "Warranty keywords or warranty documents",
      jobs: warranty,
      tone: warranty.length ? "amber" : "green",
      icon: ShieldCheck,
    },
  ];
}

function buildFieldWalkthroughReadiness({
  snapshot,
  job,
  tasks,
  photos,
  materialReadiness,
  documents,
  changeOrders,
  invoices,
}: {
  snapshot: CrmSnapshot;
  job: JobRecord;
  tasks: JobTaskRecord[];
  photos: JobPhotoRecord[];
  materialReadiness: ProductionReadiness;
  documents: DocumentRecord[];
  changeOrders: ChangeOrderRecord[];
  invoices: InvoiceRecord[];
}): FieldWalkthroughReadinessItem[] {
  const doneTasks = tasks.filter((task) => task.status === "done").length;
  const openChangeOrders = changeOrders.filter(
    (changeOrder) => changeOrder.status === "draft" || changeOrder.status === "sent",
  );
  const inspectionReadiness = getJobInspectionReadiness(snapshot, job);
  const outstandingIssue = getJobOutstandingIssue(snapshot, job);
  const invoiceReady = invoices.some(
    (invoice) => invoice.status === "sent" || invoice.status === "paid",
  );

  return [
    {
      id: "checklist",
      label: "Checklist complete",
      state: tasks.length
        ? doneTasks === tasks.length
          ? "Ready"
          : "Incomplete"
        : "Not Tracked",
      detail: tasks.length
        ? `${doneTasks} of ${tasks.length} checklist tasks complete`
        : "No production checklist tasks recorded",
      icon: ClipboardList,
    },
    {
      id: "photos",
      label: "Required photos present",
      state: photos.length ? "Needs Review" : "Not Tracked",
      detail: photos.length
        ? `${photos.length} linked job photo${photos.length === 1 ? "" : "s"} available for review`
        : "No linked job photos yet",
      icon: Camera,
    },
    {
      id: "issues",
      label: "Issues resolved",
      state: job.status === "blocked" ? "Blocked" : outstandingIssue === "No outstanding issue recorded" ? "Ready" : "Needs Review",
      detail: outstandingIssue,
      icon: AlertTriangle,
    },
    {
      id: "materials",
      label: "Materials complete",
      state: materialReadiness.label === "Ready"
        ? "Ready"
        : materialReadiness.label === "Not Recorded"
          ? "Not Tracked"
          : "Needs Review",
      detail: materialReadiness.detail,
      icon: Package,
    },
    {
      id: "change-orders",
      label: "Change orders reviewed",
      state: openChangeOrders.length ? "Needs Review" : "Ready",
      detail: openChangeOrders.length
        ? `${openChangeOrders.length} open change order${openChangeOrders.length === 1 ? "" : "s"}`
        : "No open change orders require field action",
      icon: ReceiptText,
    },
    {
      id: "customer-walkthrough",
      label: "Customer walkthrough needed",
      state: inspectionReadiness.label === "Final Complete"
        ? "Ready"
        : jobNeedsFinalWalkthrough(snapshot, job)
          ? "Needs Review"
          : "Not Tracked",
      detail: inspectionReadiness.detail,
      icon: UserRound,
    },
    {
      id: "documents",
      label: "Documents ready",
      state: documents.length ? "Needs Review" : "Not Tracked",
      detail: documents.length
        ? `${documents.length} linked document${documents.length === 1 ? "" : "s"}`
        : "No linked production documents yet",
      icon: FileText,
    },
    {
      id: "invoice",
      label: "Invoice readiness",
      state: invoiceReady ? "Ready" : invoices.length ? "Needs Review" : "Not Tracked",
      detail: invoices.length
        ? `${invoices.length} linked invoice${invoices.length === 1 ? "" : "s"}`
        : "No invoice linked; field users cannot mark jobs paid",
      icon: ReceiptText,
    },
  ];
}

function jobProductionText(job: JobRecord) {
  return [
    job.title,
    job.service_type,
    job.status,
    job.business,
    job.location,
    job.scope_of_work,
    job.notes,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function jobMatchesProductionKeywords(job: JobRecord, keywords: string[]) {
  const text = jobProductionText(job);

  return keywords.some((keyword) => text.includes(keyword));
}

function isProductionActiveJob(job: JobRecord) {
  return job.status === "scheduled" || job.status === "in_progress" || job.status === "blocked";
}

function getJobProductionProgressPercent(snapshot: CrmSnapshot, job: JobRecord) {
  const tasks = getJobTasks(snapshot, job.id);

  if (job.status === "completed" || job.status === "closed") {
    return 100;
  }

  if (!tasks.length) {
    return job.status === "in_progress" ? 35 : job.status === "scheduled" ? 15 : 0;
  }

  return Math.round(
    (tasks.filter((task) => task.status === "done").length / tasks.length) * 100,
  );
}

function getJobForemanLabel(snapshot: CrmSnapshot, job: JobRecord) {
  if (job.project_manager?.trim()) {
    return job.project_manager;
  }

  const leadAssignment = getJobAssignments(snapshot, job.id).find(
    (assignment) =>
      assignment.title.toLowerCase().includes("foreman") ||
      assignment.title.toLowerCase().includes("lead") ||
      assignment.status === "accepted",
  );

  return getEmployeeName(snapshot, leadAssignment?.employee_id ?? null) ?? "Foreman unassigned";
}

function getJobProductionScheduleWindow(snapshot: CrmSnapshot, job: JobRecord) {
  const scheduledStart = getJobScheduledStart(job);
  const scheduledEnd = getJobScheduledEnd(job);
  const event =
    getJobScheduleEvents(snapshot, job.id).find((item) => item.status === "scheduled") ??
    getJobScheduleEvents(snapshot, job.id)[0] ??
    null;
  const start = scheduledStart ?? event?.start_at ?? null;
  const end = scheduledEnd ?? event?.end_at ?? null;

  if (start && end) {
    return { start, end };
  }

  return null;
}

function rangesOverlap(
  left: { start: string; end: string },
  right: { start: string; end: string },
) {
  const leftStart = Date.parse(left.start);
  const leftEnd = Date.parse(left.end);
  const rightStart = Date.parse(right.start);
  const rightEnd = Date.parse(right.end);

  if (
    !Number.isFinite(leftStart) ||
    !Number.isFinite(leftEnd) ||
    !Number.isFinite(rightStart) ||
    !Number.isFinite(rightEnd)
  ) {
    return false;
  }

  return leftStart < rightEnd && rightStart < leftEnd;
}

function getJobMaterialReadiness(snapshot: CrmSnapshot, job: JobRecord): ProductionReadiness {
  const orders = getJobMaterialOrders(snapshot, job.id);
  const jobMaterials = getJobMaterials(snapshot, job.id);
  const delayedOrder = orders.find((order) => {
    if (!order.expected_delivery_date || order.status === "received" || order.status === "canceled") {
      return false;
    }

    return order.expected_delivery_date < todayIsoDate();
  });

  if (delayedOrder) {
    return {
      label: "Delayed",
      detail: `${delayedOrder.supplier_name} expected ${formatDate(
        delayedOrder.expected_delivery_date ?? delayedOrder.requested_date,
      )}`,
      tone: "amber",
    };
  }

  if (orders.some((order) => order.status === "received")) {
    return {
      label: "Ready",
      detail: "Received material order recorded",
      tone: "green",
    };
  }

  if (orders.some((order) => order.status === "partial")) {
    return {
      label: "Partial",
      detail: "Partially received material order",
      tone: "amber",
    };
  }

  if (orders.some((order) => order.status === "ordered")) {
    return {
      label: "Ordered",
      detail: "Material order is placed",
      tone: "blue",
    };
  }

  if (orders.some((order) => order.status === "draft")) {
    return {
      label: "Requested",
      detail: "Draft material order exists",
      tone: "blue",
    };
  }

  if (jobMaterials.length > 0) {
    return {
      label: "Not Recorded",
      detail: "Job material list exists; order readiness is not tracked",
      tone: "amber",
    };
  }

  if (isProductionActiveJob(job)) {
    return {
      label: "Request Needed",
      detail: "No material order or material list recorded",
      tone: "amber",
    };
  }

  return {
    label: "Not Recorded",
    detail: "Material readiness has not been tracked",
    tone: "blue",
  };
}

function getJobInspectionReadiness(snapshot: CrmSnapshot, job: JobRecord): ProductionReadiness {
  const inspections = snapshot.inspections.filter(
    (inspection) =>
      inspection.job_id === job.id ||
      (job.lead_id !== null && inspection.lead_id === job.lead_id) ||
      (job.customer_id !== null && inspection.customer_id === job.customer_id),
  );
  const finalInspection = inspections.find(
    (inspection) =>
      inspection.title.toLowerCase().includes("final") ||
      inspection.title.toLowerCase().includes("walkthrough"),
  );
  const openInspection = inspections.find(
    (inspection) => inspection.status === "scheduled" || inspection.status === "draft",
  );

  if (finalInspection?.status === "completed") {
    return {
      label: "Final Complete",
      detail: finalInspection.title,
      tone: "green",
    };
  }

  if (finalInspection) {
    return {
      label: "Final Walkthrough",
      detail: `${finalInspection.title} · ${inspectionStatusLabel(finalInspection.status)}`,
      tone: "amber",
    };
  }

  if (openInspection) {
    return {
      label: "Inspection Required",
      detail: `${openInspection.title} · ${inspectionStatusLabel(openInspection.status)}`,
      tone: "amber",
    };
  }

  if (inspections.some((inspection) => inspection.status === "completed")) {
    return {
      label: "Inspection Complete",
      detail: "Completed inspection linked",
      tone: "green",
    };
  }

  return {
    label: "Inspection Not Recorded",
    detail: "No linked inspection record",
    tone: "blue",
  };
}

function getJobPriorityLabel(snapshot: CrmSnapshot, job: JobRecord) {
  const inspection = snapshot.inspections.find((item) => item.job_id === job.id);
  const lead = job.lead_id ? snapshot.leads.find((item) => item.id === job.lead_id) : null;

  return inspection?.priority ?? lead?.priority ?? "normal";
}

function getJobOutstandingIssue(snapshot: CrmSnapshot, job: JobRecord) {
  const materialReadiness = getJobMaterialReadiness(snapshot, job);
  const inspectionReadiness = getJobInspectionReadiness(snapshot, job);

  if (!hasSavedJobSchedule(job) && isProductionActiveJob(job)) {
    return "Missing production schedule";
  }

  if (!jobHasCrew(snapshot, job) && isProductionActiveJob(job)) {
    return "Crew unassigned";
  }

  if (materialReadiness.tone === "amber") {
    return materialReadiness.label;
  }

  if (inspectionReadiness.tone === "amber") {
    return inspectionReadiness.label;
  }

  if (job.status === "blocked") {
    return "Blocked";
  }

  return "No outstanding issue recorded";
}

function getJobWeatherDelayReadiness(job: JobRecord): ProductionReadiness {
  const text = jobProductionText(job);
  const hasWeatherSignal = ["weather", "rain", "wind", "hail", "monsoon", "storm"].some(
    (keyword) => text.includes(keyword),
  );
  const hasDelaySignal = ["delay", "delayed", "pause", "paused", "blocked"].some(
    (keyword) => text.includes(keyword),
  );

  if (hasWeatherSignal && hasDelaySignal) {
    return {
      label: "Weather delay noted",
      detail: "Existing job text includes weather and delay signals",
      tone: "amber",
    };
  }

  if (hasWeatherSignal) {
    return {
      label: "Weather note found",
      detail: "Existing job text mentions weather; no delay is confirmed",
      tone: "blue",
    };
  }

  return {
    label: "Not Tracked",
    detail: "Weather-delay tracking needs a future workflow",
    tone: "blue",
  };
}

function jobNeedsFinalWalkthrough(snapshot: CrmSnapshot, job: JobRecord) {
  const tasks = getJobTasks(snapshot, job.id);

  return (
    isProductionActiveJob(job) &&
    tasks.length > 0 &&
    tasks.every((task) => task.status === "done") &&
    job.status !== "completed" &&
    job.status !== "closed"
  );
}

function jobHasWarrantySignal(snapshot: CrmSnapshot, job: JobRecord) {
  return (
    jobMatchesProductionKeywords(job, ["warranty"]) ||
    getJobDocuments(snapshot, job).some((document) => document.category === "warranty")
  );
}

function buildProductionBoardColumns(
  snapshot: CrmSnapshot,
  jobs: JobRecord[] = snapshot.jobs,
): ProductionBoardColumn[] {
  const unscheduled = jobs.filter(
    (job) =>
      isProductionActiveJob(job) &&
      !hasSavedJobSchedule(job) &&
      !hasUpcomingScheduledEvent(getJobScheduleEvents(snapshot, job.id)),
  );
  const scheduled = jobs.filter(
    (job) =>
      job.status === "scheduled" ||
      hasSavedJobSchedule(job) ||
      hasUpcomingScheduledEvent(getJobScheduleEvents(snapshot, job.id)),
  );
  const waitingOnCustomer = jobs.filter((job) => {
    const text = jobProductionText(job);

    return (
      job.status === "blocked" &&
      (text.includes("customer") ||
        text.includes("approval") ||
        text.includes("hoa") ||
        getJobChangeOrders(snapshot, job.id).some((changeOrder) => changeOrder.status === "sent"))
    );
  });
  const waitingOnMaterials = jobs.filter((job) => {
    const readiness = getJobMaterialReadiness(snapshot, job);

    return (
      isProductionActiveJob(job) &&
      ["Request Needed", "Requested", "Ordered", "Partial", "Delayed"].includes(
        readiness.label,
      )
    );
  });
  const inspectionRequired = jobs.filter((job) => {
    const readiness = getJobInspectionReadiness(snapshot, job);

    return readiness.label === "Inspection Required";
  });
  const finalWalkthrough = jobs.filter((job) => jobNeedsFinalWalkthrough(snapshot, job));
  const completed = jobs.filter(
    (job) => job.status === "completed" || job.status === "closed",
  );
  const warranty = jobs.filter((job) => jobHasWarrantySignal(snapshot, job));

  return [
    {
      id: "unscheduled",
      label: "Unscheduled",
      detail: "Active jobs missing production dates",
      jobs: unscheduled,
      tone: unscheduled.length ? "amber" : "green",
      icon: CalendarClock,
    },
    {
      id: "scheduled",
      label: "Scheduled",
      detail: "Saved dates or scheduled job events",
      jobs: scheduled,
      tone: "blue",
      icon: CalendarClock,
    },
    {
      id: "in-production",
      label: "In Production",
      detail: "Jobs marked in progress",
      jobs: jobs.filter((job) => job.status === "in_progress"),
      tone: "blue",
      icon: Activity,
    },
    {
      id: "customer",
      label: "Waiting on Customer",
      detail: "Blocked by customer, HOA, or approval signals",
      jobs: waitingOnCustomer,
      tone: waitingOnCustomer.length ? "amber" : "green",
      icon: UserRound,
    },
    {
      id: "materials",
      label: "Waiting on Materials",
      detail: "Material readiness is not ready",
      jobs: waitingOnMaterials,
      tone: waitingOnMaterials.length ? "amber" : "green",
      icon: Package,
    },
    {
      id: "inspection",
      label: "Inspection Required",
      detail: "Open linked inspection work",
      jobs: inspectionRequired,
      tone: inspectionRequired.length ? "amber" : "green",
      icon: ClipboardList,
    },
    {
      id: "walkthrough",
      label: "Final Walkthrough",
      detail: "Checklist complete, still open",
      jobs: finalWalkthrough,
      tone: finalWalkthrough.length ? "amber" : "green",
      icon: CheckCircle2,
    },
    {
      id: "completed",
      label: "Completed",
      detail: "Completed or closed jobs",
      jobs: completed,
      tone: completed.length ? "green" : "blue",
      icon: CheckCircle2,
    },
    {
      id: "warranty",
      label: "Warranty",
      detail: "Warranty jobs or warranty documents",
      jobs: warranty,
      tone: warranty.length ? "amber" : "green",
      icon: ShieldCheck,
    },
  ];
}

function getJobBranchLocation(job: JobRecord) {
  const location = getJobDisplayLocation(job).toLowerCase();
  const address = getJobDisplayAddress(job).toLowerCase();

  if (location.includes("tucson") || address.includes("tucson")) {
    return "Tucson";
  }

  if (location.includes("phoenix") || address.includes("phoenix")) {
    return "Phoenix";
  }

  return "Other";
}

function buildScheduleConflicts(snapshot: CrmSnapshot): ScheduleConflict[] {
  const conflicts: ScheduleConflict[] = [];
  const activeScheduledJobs = snapshot.jobs
    .map((job) => ({
      job,
      window: getJobProductionScheduleWindow(snapshot, job),
      crew: getJobCrewLabel(snapshot, job),
      foreman: getJobForemanLabel(snapshot, job),
    }))
    .filter((item) => item.window !== null);

  activeScheduledJobs.forEach((item, index) => {
    activeScheduledJobs.slice(index + 1).forEach((otherItem) => {
      if (!item.window || !otherItem.window || !rangesOverlap(item.window, otherItem.window)) {
        return;
      }

      if (item.crew !== "Crew needed" && item.crew === otherItem.crew) {
        conflicts.push({
          id: `crew-${item.job.id}-${otherItem.job.id}`,
          label: "Crew overlap",
          detail: `${item.crew} is scheduled on ${item.job.title} and ${otherItem.job.title}`,
          job: item.job,
          tone: "amber",
        });
      }

      if (
        item.foreman !== "Foreman unassigned" &&
        item.foreman === otherItem.foreman
      ) {
        conflicts.push({
          id: `foreman-${item.job.id}-${otherItem.job.id}`,
          label: "Foreman overlap",
          detail: `${item.foreman} is scheduled on ${item.job.title} and ${otherItem.job.title}`,
          job: item.job,
          tone: "amber",
        });
      }
    });
  });

  snapshot.jobs.forEach((job) => {
    if (countScheduleEventConflicts(getJobScheduleEvents(snapshot, job.id)) > 0) {
      conflicts.push({
        id: `job-events-${job.id}`,
        label: "Job schedule conflict",
        detail: `${job.title} has overlapping schedule records`,
        job,
        tone: "amber",
      });
    }

    if (isProductionActiveJob(job) && !getJobProductionScheduleWindow(snapshot, job)) {
      conflicts.push({
        id: `missing-schedule-${job.id}`,
        label: "Missing schedule",
        detail: `${job.title} is active without production dates`,
        job,
        tone: "amber",
      });
    }

    if (
      (job.status === "scheduled" || getJobProductionScheduleWindow(snapshot, job)) &&
      !jobHasCrew(snapshot, job)
    ) {
      conflicts.push({
        id: `missing-crew-${job.id}`,
        label: "Missing crew",
        detail: `${job.title} is scheduled without a crew`,
        job,
        tone: "amber",
      });
    }
  });

  snapshot.inspections.forEach((inspection) => {
    if (!inspection.job_id || !inspection.scheduled_start || !inspection.scheduled_end) {
      return;
    }

    const job = snapshot.jobs.find((item) => item.id === inspection.job_id) ?? null;
    const window = job ? getJobProductionScheduleWindow(snapshot, job) : null;

    if (job && window && rangesOverlap(window, {
      start: inspection.scheduled_start,
      end: inspection.scheduled_end,
    })) {
      conflicts.push({
        id: `inspection-${inspection.id}`,
        label: "Inspection overlap",
        detail: `${inspection.title} overlaps production schedule for ${job.title}`,
        job,
        tone: "amber",
      });
    }
  });

  return conflicts;
}

function getDispatchWindowRange(date: string, view: DispatchView) {
  return {
    startDate: date,
    endDate: view === "week" ? addDaysToIsoDate(date, 6) : date,
  };
}

function dispatchItemMatchesDateRange(item: DispatchItem, startDate: string, endDate: string) {
  if (!item.start && !item.end) {
    return true;
  }

  const itemStart = (item.start ?? item.end)?.slice(0, 10);
  const itemEnd = (item.end ?? item.start)?.slice(0, 10);

  if (!itemStart || !itemEnd) {
    return true;
  }

  return itemStart <= endDate && itemEnd >= startDate;
}

function getDispatchStatusBucket(item: DispatchItem): DispatchStatusFilter {
  if (!item.start && !item.end) {
    return "unscheduled";
  }

  if (item.status === "in_progress") {
    return "in_progress";
  }

  if (item.status === "blocked" || item.status === "follow_up_required" || item.status === "needs_review") {
    return "blocked";
  }

  if (
    item.status === "completed" ||
    item.status === "closed" ||
    item.status === "passed" ||
    item.status === "no_work_needed"
  ) {
    return "completed";
  }

  return "scheduled";
}

function buildDispatchItems(snapshot: CrmSnapshot): DispatchItem[] {
  const jobItems: DispatchItem[] = snapshot.jobs.map((job) => {
    const company = snapshot.companies.find((item) => item.id === job.company_id) ?? null;
    const window = getJobProductionScheduleWindow(snapshot, job);

    return {
      id: `job:${job.id}`,
      kind: "job",
      companyId: job.company_id,
      company,
      title: job.title,
      target: getJobTargetName(snapshot, job),
      address: getJobDisplayAddress(job),
      status: job.status,
      statusLabel: jobStatusLabel(job.status),
      serviceLabel: serviceLabel(job.service_type),
      start: window?.start ?? getJobScheduledStart(job),
      end: window?.end ?? getJobScheduledEnd(job),
      crew: getJobCrewLabel(snapshot, job),
      foreman: getJobForemanLabel(snapshot, job),
      priority: getJobPriorityLabel(snapshot, job),
      job,
      inspection: null,
      materialReadiness: getJobMaterialReadiness(snapshot, job),
      inspectionReadiness: getJobInspectionReadiness(snapshot, job),
    };
  });
  const inspectionItems: DispatchItem[] = snapshot.inspections
    .filter((inspection) => inspection.status !== "canceled")
    .map((inspection) => {
      const linkedJob = inspection.job_id
        ? snapshot.jobs.find((job) => job.id === inspection.job_id) ?? null
        : null;
      const company =
        snapshot.companies.find((item) => item.id === inspection.company_id) ??
        (linkedJob
          ? snapshot.companies.find((item) => item.id === linkedJob.company_id) ?? null
          : null);
      const inspectorLabel = inspection.assigned_inspector?.trim() || null;

      return {
        id: `inspection:${inspection.id}`,
        kind: "inspection",
        companyId: inspection.company_id,
        company,
        title: inspection.title,
        target: getInspectionTargetName(snapshot, inspection),
        address: getInspectionPropertyAddress(snapshot, inspection),
        status: inspection.status,
        statusLabel: inspectionStatusLabel(inspection.status),
        serviceLabel: serviceLabel(getInspectionServiceType(inspection)),
        start: inspection.scheduled_start,
        end: inspection.scheduled_end,
        crew: linkedJob
          ? getJobCrewLabel(snapshot, linkedJob)
          : inspectorLabel ?? "Inspector unassigned",
        foreman:
          inspectorLabel ??
          (linkedJob ? getJobForemanLabel(snapshot, linkedJob) : "Inspector unassigned"),
        priority: inspection.priority ?? "normal",
        job: linkedJob,
        inspection,
        materialReadiness: linkedJob ? getJobMaterialReadiness(snapshot, linkedJob) : null,
        inspectionReadiness: null,
      };
    });

  return [...jobItems, ...inspectionItems].sort((a, b) => {
    const left = a.start ?? a.end ?? "9999-12-31T00:00:00.000Z";
    const right = b.start ?? b.end ?? "9999-12-31T00:00:00.000Z";

    return left.localeCompare(right);
  });
}

function filterDispatchItems(
  items: DispatchItem[],
  filters: {
    view: DispatchView;
    date: string;
    company: string;
    crew: string;
    foreman: string;
    status: DispatchStatusFilter;
    search: string;
  },
) {
  const { startDate, endDate } = getDispatchWindowRange(filters.date, filters.view);
  const query = filters.search.trim().toLowerCase();

  return items.filter((item) => {
    const searchableText = [
      item.title,
      item.target,
      item.address,
      item.company?.name,
      item.crew,
      item.foreman,
      item.serviceLabel,
      item.statusLabel,
      item.materialReadiness?.label,
      item.inspectionReadiness?.label,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    return (
      dispatchItemMatchesDateRange(item, startDate, endDate) &&
      (filters.company === "all" || item.companyId === filters.company) &&
      (filters.crew === "all" ||
        (filters.crew === "unassigned" && item.crew.includes("unassigned")) ||
        (filters.crew === "unassigned" && item.crew === "Crew needed") ||
        item.crew === filters.crew) &&
      (filters.foreman === "all" ||
        (filters.foreman === "unassigned" &&
          (item.foreman.includes("unassigned") || item.foreman === "Foreman unassigned")) ||
        item.foreman === filters.foreman) &&
      (filters.status === "all" || getDispatchStatusBucket(item) === filters.status) &&
      (!query || searchableText.includes(query))
    );
  });
}

function buildCrewScheduleGroups(snapshot: CrmSnapshot, jobs: JobRecord[]): CrewScheduleGroup[] {
  const conflicts = buildScheduleConflicts(snapshot);
  const grouped = new Map<string, CrewScheduleGroup>();

  jobs.forEach((job) => {
    const crew = getJobCrewLabel(snapshot, job);
    const company = snapshot.companies.find((item) => item.id === job.company_id) ?? null;
    const id = `${job.company_id}:${crew}`;

    if (!grouped.has(id)) {
      grouped.set(id, {
        id,
        crew,
        foreman: getJobForemanLabel(snapshot, job),
        company,
        jobs: [],
        conflicts: [],
      });
    }

    grouped.get(id)?.jobs.push(job);
  });

  grouped.forEach((group) => {
    group.conflicts = conflicts.filter(
      (conflict) => conflict.job && group.jobs.some((job) => job.id === conflict.job?.id),
    );
    group.jobs.sort((a, b) => {
      const left = getJobProductionScheduleWindow(snapshot, a)?.start ?? a.updated_at;
      const right = getJobProductionScheduleWindow(snapshot, b)?.start ?? b.updated_at;

      return left.localeCompare(right);
    });
  });

  return [...grouped.values()].sort((a, b) => a.crew.localeCompare(b.crew));
}

function buildProductionLogItems(snapshot: CrmSnapshot, job: JobRecord): ProductionLogItem[] {
  const items: ProductionLogItem[] = buildJobActivityItems(snapshot, job).map((item) => ({
    id: item.id,
    label: item.label,
    detail: item.detail,
    occurredAt: item.occurredAt,
    meta: item.meta ?? "Activity",
    icon:
      item.label.includes("Photo")
        ? Camera
        : item.label.includes("Material")
          ? Package
          : item.label.includes("Invoice")
            ? ReceiptText
            : item.label.includes("Change")
              ? ReceiptText
              : item.label.includes("Checklist")
                ? ClipboardList
                : Activity,
  }));

  snapshot.dailyLogs
    .filter((log) => log.job_id === job.id)
    .forEach((log) => {
      items.push({
        id: `daily-log-${log.id}`,
        label: "Daily production log",
        detail: log.work_completed,
        occurredAt: log.log_date,
        meta: log.blockers ? "Blocker recorded" : "Crew log",
        icon: ClipboardList,
      });
    });

  return items
    .sort((a, b) => {
      const left = a.occurredAt ? Date.parse(a.occurredAt) : 0;
      const right = b.occurredAt ? Date.parse(b.occurredAt) : 0;

      return right - left;
    })
    .slice(0, 8);
}

function buildPhotoProgressGroups(photos: JobPhotoRecord[]): PhotoProgressGroup[] {
  const groups = [
    { id: "before", label: "Before", keywords: ["before"] },
    { id: "during", label: "During", keywords: ["during", "progress"] },
    { id: "after", label: "After", keywords: ["after"] },
    { id: "issue", label: "Issue", keywords: ["issue", "damage", "repair", "leak"] },
    { id: "completion", label: "Completion", keywords: ["completion", "complete", "final"] },
  ];

  return groups.map((group) => ({
    id: group.id,
    label: group.label,
    photos: photos.filter((photo) => {
      const text = [photo.label, photo.caption, photo.file_path]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();

      return group.keywords.some((keyword) => text.includes(keyword));
    }),
  }));
}

function buildJobProductionBuckets({
  snapshot,
  onSelectJob,
  onStatusFilter,
  onScheduleFilter,
}: {
  snapshot: CrmSnapshot;
  onSelectJob: (job: JobRecord) => void;
  onStatusFilter: (status: JobStatus | "all") => void;
  onScheduleFilter: (filter: JobScheduleFilter) => void;
}): JobProductionBucket[] {
  const today = todayIsoDate();
  const activeJobs = snapshot.jobs.filter(isProductionActiveJob);
  const scheduledToday = snapshot.jobs.filter((job) =>
    getJobScheduleDateParts(snapshot, job).some((date) => date === today),
  );
  const waitingOnCustomer = activeJobs.filter((job) => {
    const text = jobProductionText(job);
    const hasCustomerSignal =
      text.includes("customer") ||
      text.includes("approval") ||
      text.includes("hoa") ||
      getJobChangeOrders(snapshot, job.id).some((changeOrder) => changeOrder.status === "sent");

    return job.status === "blocked" && hasCustomerSignal;
  });
  const waitingOnMaterial = activeJobs.filter((job) =>
    getJobMaterialOrders(snapshot, job.id).some(
      (order) => order.status === "ordered" || order.status === "partial",
    ),
  );
  const inProduction = snapshot.jobs.filter((job) => job.status === "in_progress");
  const finalWalkthrough = activeJobs.filter((job) => {
    const tasks = getJobTasks(snapshot, job.id);
    return (
      tasks.length > 0 &&
      tasks.every((task) => task.status === "done") &&
      job.status !== "completed" &&
      job.status !== "closed"
    );
  });
  const completed = snapshot.jobs.filter(
    (job) => job.status === "completed" || job.status === "closed",
  );
  const warranty = snapshot.jobs.filter((job) =>
    jobMatchesProductionKeywords(job, ["warranty"]) ||
    getJobDocuments(snapshot, job).some((document) => document.category === "warranty"),
  );

  const openFirst = (jobs: JobRecord[], fallback?: () => void) => {
    if (jobs[0]) {
      onSelectJob(jobs[0]);
      return;
    }

    fallback?.();
  };

  return [
    {
      id: "active",
      label: "Active jobs",
      detail: "Scheduled, in production, or blocked",
      value: activeJobs.length,
      jobs: activeJobs,
      tone: activeJobs.length ? "blue" : "green",
      icon: Home,
      onClick: () => {
        onStatusFilter("all");
        openFirst(activeJobs);
      },
    },
    {
      id: "today",
      label: "Scheduled today",
      detail: "Jobs or events dated for today",
      value: scheduledToday.length,
      jobs: scheduledToday,
      tone: scheduledToday.length ? "amber" : "green",
      icon: CalendarClock,
      onClick: () => {
        onScheduleFilter("today");
        openFirst(scheduledToday);
      },
    },
    {
      id: "customer",
      label: "Waiting on customer",
      detail: "Blocked with customer, HOA, or approval signals",
      value: waitingOnCustomer.length,
      jobs: waitingOnCustomer,
      tone: waitingOnCustomer.length ? "amber" : "green",
      icon: UserRound,
      onClick: () => {
        onStatusFilter("blocked");
        openFirst(waitingOnCustomer);
      },
    },
    {
      id: "materials",
      label: "Waiting on material",
      detail: "Ordered or partially received material orders",
      value: waitingOnMaterial.length,
      jobs: waitingOnMaterial,
      tone: waitingOnMaterial.length ? "amber" : "green",
      icon: Package,
      onClick: () => openFirst(waitingOnMaterial),
    },
    {
      id: "production",
      label: "In production",
      detail: "Jobs currently marked in progress",
      value: inProduction.length,
      jobs: inProduction,
      tone: inProduction.length ? "blue" : "green",
      icon: Activity,
      onClick: () => {
        onStatusFilter("in_progress");
        openFirst(inProduction);
      },
    },
    {
      id: "walkthrough",
      label: "Final walkthrough",
      detail: "Checklist complete, still open",
      value: finalWalkthrough.length,
      jobs: finalWalkthrough,
      tone: finalWalkthrough.length ? "amber" : "green",
      icon: CheckCircle2,
      onClick: () => openFirst(finalWalkthrough),
    },
    {
      id: "completed",
      label: "Completed",
      detail: "Completed or closed production",
      value: completed.length,
      jobs: completed,
      tone: completed.length ? "green" : "blue",
      icon: CheckCircle2,
      onClick: () => {
        onStatusFilter("completed");
        openFirst(completed);
      },
    },
    {
      id: "warranty",
      label: "Warranty",
      detail: "Warranty jobs or linked warranty documents",
      value: warranty.length,
      jobs: warranty,
      tone: warranty.length ? "amber" : "green",
      icon: ShieldCheck,
      onClick: () => openFirst(warranty),
    },
  ];
}

function buildCrewAssignmentSummaries(snapshot: CrmSnapshot) {
  return snapshot.jobs
    .filter((job) => isProductionActiveJob(job) || hasSavedJobSchedule(job))
    .map((job) => {
      const company = snapshot.companies.find((item) => item.id === job.company_id) ?? null;

      return {
        job,
        company,
        crew: getJobCrewLabel(snapshot, job),
        foreman: getJobForemanLabel(snapshot, job),
        scheduledDate: getJobScheduleSummary(snapshot, job),
        progress: getJobProductionProgressPercent(snapshot, job),
      };
    })
    .sort((a, b) => {
      const left = getJobScheduledStart(a.job) ?? a.job.start_date ?? a.job.updated_at;
      const right = getJobScheduledStart(b.job) ?? b.job.start_date ?? b.job.updated_at;

      return left.localeCompare(right);
    });
}

