function buildJobProductionTimelineItems(
  snapshot: CrmSnapshot,
  job: JobRecord,
): JobProductionTimelineItem[] {
  const estimate = job.estimate_id
    ? snapshot.estimates.find((item) => item.id === job.estimate_id) ?? null
    : null;
  const inspections = snapshot.inspections.filter(
    (inspection) =>
      inspection.job_id === job.id ||
      (job.lead_id !== null && inspection.lead_id === job.lead_id) ||
      (job.customer_id !== null && inspection.customer_id === job.customer_id),
  );
  const contract = getJobDocuments(snapshot, job).find(
    (document) => document.category === "contract",
  );
  const materialOrder = getJobMaterialOrders(snapshot, job.id)[0] ?? null;
  const schedule = getJobScheduleEvents(snapshot, job.id).find(
    (event) => event.status === "scheduled",
  );
  const finalInspection = inspections.find(
    (inspection) =>
      inspection.status === "completed" ||
      inspection.report_created_at !== null ||
      inspection.title.toLowerCase().includes("final"),
  );
  const invoice = getJobInvoices(snapshot, job.id)[0] ?? null;
  const paidInvoice = getJobInvoices(snapshot, job.id).find(
    (item) => item.status === "paid" || item.balance_due <= 0,
  );
  const completionDocument = getJobDocuments(snapshot, job).find(
    (document) => document.category === "completion_certificate",
  );

  const item = ({
    id,
    label,
    detail,
    occurredAt,
    pendingDetail,
    icon,
    complete,
  }: {
    id: string;
    label: string;
    detail: string;
    occurredAt: string | null;
    pendingDetail: string;
    icon: typeof Home;
    complete: boolean;
  }): JobProductionTimelineItem => ({
    id,
    label,
    detail: complete ? detail : pendingDetail,
    occurredAt,
    meta: complete && occurredAt ? formatDate(occurredAt) : "Not recorded",
    status: complete ? "complete" : "pending",
    icon,
  });

  const timeline = [
    item({
      id: "inspection",
      label: "Inspection",
      detail: inspections[0]?.title ?? "Inspection linked",
      occurredAt:
        inspections[0]?.completed_at ??
        inspections[0]?.scheduled_start ??
        inspections[0]?.created_at ??
        null,
      pendingDetail: "No linked inspection yet",
      icon: ClipboardList,
      complete: inspections.length > 0,
    }),
    item({
      id: "estimate",
      label: "Estimate",
      detail: estimate ? `${estimate.title} · ${formatMoney(estimate.total)}` : "Estimate linked",
      occurredAt: estimate?.issue_date ?? estimate?.created_at ?? null,
      pendingDetail: "No estimate linked yet",
      icon: FileText,
      complete: Boolean(estimate),
    }),
    item({
      id: "contract",
      label: "Contract",
      detail: contract ? `${contract.title} · ${documentStatusLabel(contract.status)}` : "Contract ready",
      occurredAt: contract?.updated_at ?? null,
      pendingDetail: "No contract document linked",
      icon: FileText,
      complete: Boolean(contract),
    }),
    item({
      id: "material",
      label: "Material ordered",
      detail: materialOrder ? `${materialOrder.supplier_name} · ${materialOrderStatusLabel(materialOrder.status)}` : "Material order linked",
      occurredAt: materialOrder?.requested_date ?? null,
      pendingDetail: "No material order linked",
      icon: Package,
      complete: Boolean(materialOrder),
    }),
    item({
      id: "scheduled",
      label: "Production scheduled",
      detail: schedule ? schedule.title : "Production dates saved",
      occurredAt: schedule?.start_at ?? getJobScheduledStart(job) ?? job.start_date,
      pendingDetail: "No production schedule saved",
      icon: CalendarClock,
      complete: Boolean(schedule || hasSavedJobSchedule(job)),
    }),
    item({
      id: "started",
      label: "Work started",
      detail: job.status === "in_progress" ? "Job is in production" : "Production started",
      occurredAt: job.status === "in_progress" ? job.updated_at : null,
      pendingDetail: "Not marked in progress",
      icon: Activity,
      complete: job.status === "in_progress" || job.status === "completed" || job.status === "closed",
    }),
    item({
      id: "final",
      label: "Final inspection",
      detail:
        finalInspection?.title ??
        completionDocument?.title ??
        "Completion documentation linked",
      occurredAt:
        finalInspection?.completed_at ??
        finalInspection?.updated_at ??
        completionDocument?.updated_at ??
        null,
      pendingDetail: "No final inspection or completion certificate yet",
      icon: CheckCircle2,
      complete: Boolean(finalInspection || completionDocument),
    }),
    item({
      id: "invoice",
      label: "Invoice",
      detail: invoice ? `${invoice.invoice_number} · ${formatMoney(invoice.total)}` : "Invoice linked",
      occurredAt: invoice?.issue_date ?? null,
      pendingDetail: "No invoice linked yet",
      icon: ReceiptText,
      complete: Boolean(invoice),
    }),
    item({
      id: "paid",
      label: "Paid",
      detail: paidInvoice ? `${paidInvoice.invoice_number} paid` : "Payment posted",
      occurredAt: paidInvoice?.updated_at ?? null,
      pendingDetail: "No paid invoice recorded",
      icon: DollarSign,
      complete: Boolean(paidInvoice),
    }),
  ];
  const firstPendingIndex = timeline.findIndex((entry) => entry.status === "pending");

  return timeline.map((entry, index) =>
    index === firstPendingIndex ? { ...entry, status: "current" } : entry,
  );
}

function getChangeOrderTargetName(snapshot: CrmSnapshot, changeOrder: ChangeOrderRecord) {
  return (
    getJobName(snapshot, changeOrder.job_id) ??
    getCustomerName(snapshot, changeOrder.customer_id) ??
    snapshot.estimates.find((estimate) => estimate.id === changeOrder.estimate_id)?.title ??
    "Unassigned"
  );
}

function getDocumentTargetName(snapshot: CrmSnapshot, document: DocumentRecord) {
  return (
    getCustomerName(snapshot, document.customer_id) ??
    snapshot.leads.find((lead) => lead.id === document.lead_id)?.contact_name ??
    getJobName(snapshot, document.job_id) ??
    snapshot.estimates.find((estimate) => estimate.id === document.estimate_id)?.title ??
    snapshot.inspections.find((inspection) => inspection.id === document.inspection_id)
      ?.title ??
    snapshot.invoices.find((invoice) => invoice.id === document.invoice_id)
      ?.invoice_number ??
    snapshot.changeOrders.find((changeOrder) => changeOrder.id === document.change_order_id)
      ?.title ??
    "General"
  );
}

function getDocumentAssociationSummary(snapshot: CrmSnapshot, document: DocumentRecord) {
  const job = document.job_id
    ? snapshot.jobs.find((item) => item.id === document.job_id) ?? null
    : null;
  const invoice = document.invoice_id
    ? snapshot.invoices.find((item) => item.id === document.invoice_id) ?? null
    : null;
  const directLead = document.lead_id
    ? snapshot.leads.find((item) => item.id === document.lead_id) ?? null
    : null;
  const directInspection = document.inspection_id
    ? snapshot.inspections.find((item) => item.id === document.inspection_id) ?? null
    : null;
  const estimate = document.estimate_id
    ? snapshot.estimates.find((item) => item.id === document.estimate_id) ?? null
    : job?.estimate_id
      ? snapshot.estimates.find((item) => item.id === job.estimate_id) ?? null
      : invoice?.estimate_id
        ? snapshot.estimates.find((item) => item.id === invoice.estimate_id) ?? null
        : null;
  const customer =
    (document.customer_id
      ? snapshot.customers.find((item) => item.id === document.customer_id)
      : null) ??
    (job?.customer_id
      ? snapshot.customers.find((item) => item.id === job.customer_id)
      : null) ??
    (estimate?.customer_id
      ? snapshot.customers.find((item) => item.id === estimate.customer_id)
      : null) ??
    (invoice?.customer_id
      ? snapshot.customers.find((item) => item.id === invoice.customer_id)
      : null) ??
    null;
  const lead =
    directLead ??
    (job?.lead_id ? snapshot.leads.find((item) => item.id === job.lead_id) : null) ??
    (estimate?.lead_id
      ? snapshot.leads.find((item) => item.id === estimate.lead_id)
      : null);
  const addressParts = customer
    ? [
        customer.property_address,
        customer.city,
        customer.state,
        customer.postal_code,
      ]
    : lead
      ? [lead.property_address, lead.city, lead.state, lead.postal_code]
      : [];

  return {
    customerName: customer?.display_name ?? lead?.contact_name ?? "Unassigned",
    contact: customer?.contact_name ?? lead?.contact_name ?? "No contact",
    email: customer?.email ?? lead?.email ?? "No email",
    phone: customer?.phone ?? lead?.phone ?? "No phone",
    property:
      document.property_address ||
      job?.property_address ||
      directInspection?.property_address ||
      addressParts.filter(Boolean).join(", ") ||
      "No property linked",
    jobTitle: job?.title ?? "No job linked",
    source: getDocumentTargetName(snapshot, document),
  };
}

type DocumentActivityItem = {
  id: string;
  label: string;
  detail: string;
  occurredAt: string | null;
};

type DocumentLibraryDetails = {
  association: ReturnType<typeof getDocumentAssociationSummary>;
  libraryCategory: DocumentLibraryCategory;
  relationTypes: DocumentRelationFilter[];
  tags: string[];
  uploadStatus: string;
  uploadTone: "blue" | "green" | "amber";
  previewMode: string;
  relatedCustomer: CustomerRecord | null;
  relatedLead: LeadRecord | null;
  relatedEstimate: EstimateRecord | null;
  relatedJob: JobRecord | null;
  relatedInspection: InspectionRecord | null;
  relatedInvoice: InvoiceRecord | null;
  relatedChangeOrder: ChangeOrderRecord | null;
  signatures: SignatureRecord[];
  activity: DocumentActivityItem[];
};

function uniqueDocumentStrings(values: Array<string | null | undefined>) {
  return Array.from(
    new Set(values.map((value) => value?.trim()).filter((value): value is string => Boolean(value))),
  );
}

function getLeadIsOpportunity(lead: LeadRecord | null) {
  return Boolean(
    lead &&
      (lead.pipeline_stage !== "new_lead" ||
        lead.status === "qualified" ||
        lead.status === "estimate_sent" ||
        lead.status === "won" ||
        lead.status === "lost" ||
        lead.estimated_value > 0),
  );
}

function getDocumentRelatedRecords(
  snapshot: CrmSnapshot,
  document: DocumentRecord,
) {
  const job = document.job_id
    ? snapshot.jobs.find((item) => item.id === document.job_id) ?? null
    : null;
  const invoice = document.invoice_id
    ? snapshot.invoices.find((item) => item.id === document.invoice_id) ?? null
    : null;
  const changeOrder = document.change_order_id
    ? snapshot.changeOrders.find((item) => item.id === document.change_order_id) ?? null
    : null;
  const directLead = document.lead_id
    ? snapshot.leads.find((item) => item.id === document.lead_id) ?? null
    : null;
  const directInspection = document.inspection_id
    ? snapshot.inspections.find((item) => item.id === document.inspection_id) ?? null
    : null;
  const estimate = document.estimate_id
    ? snapshot.estimates.find((item) => item.id === document.estimate_id) ?? null
    : job?.estimate_id
      ? snapshot.estimates.find((item) => item.id === job.estimate_id) ?? null
      : invoice?.estimate_id
        ? snapshot.estimates.find((item) => item.id === invoice.estimate_id) ?? null
        : changeOrder?.estimate_id
          ? snapshot.estimates.find((item) => item.id === changeOrder.estimate_id) ?? null
          : null;
  const customer =
    (document.customer_id
      ? snapshot.customers.find((item) => item.id === document.customer_id) ?? null
      : null) ??
    (job?.customer_id
      ? snapshot.customers.find((item) => item.id === job.customer_id) ?? null
      : null) ??
    (estimate?.customer_id
      ? snapshot.customers.find((item) => item.id === estimate.customer_id) ?? null
      : null) ??
    (invoice?.customer_id
      ? snapshot.customers.find((item) => item.id === invoice.customer_id) ?? null
      : null) ??
    (changeOrder?.customer_id
      ? snapshot.customers.find((item) => item.id === changeOrder.customer_id) ?? null
      : null);
  const lead =
    directLead ??
    (job?.lead_id ? snapshot.leads.find((item) => item.id === job.lead_id) ?? null : null) ??
    (estimate?.lead_id
      ? snapshot.leads.find((item) => item.id === estimate.lead_id) ?? null
      : null) ??
    (customer?.id
      ? snapshot.leads.find((item) => item.customer_id === customer.id) ?? null
      : null) ??
    (document.template_key?.includes("lead") || document.template_key?.includes("opportunity")
      ? snapshot.leads.find((item) => document.title.includes(item.contact_name)) ?? null
      : null);
  const inspection =
    directInspection ??
    snapshot.inspections.find((item) => item.report_document_id === document.id) ??
    (job ? snapshot.inspections.find((item) => item.job_id === job.id) ?? null : null) ??
    (estimate
      ? snapshot.inspections.find((item) => item.estimate_id === estimate.id) ?? null
      : null) ??
    (lead ? snapshot.inspections.find((item) => item.lead_id === lead.id) ?? null : null) ??
    null;

  return {
    customer,
    lead,
    estimate,
    job,
    inspection,
    invoice,
    changeOrder,
  };
}

function getDocumentLibraryCategory(
  document: DocumentRecord,
  related: ReturnType<typeof getDocumentRelatedRecords>,
  signatures: SignatureRecord[],
): DocumentLibraryCategory {
  const searchable = [
    document.title,
    document.body,
    document.template_key,
    document.file_url,
    document.file_name,
    document.storage_path,
    document.property_address,
    getDocumentTags(document).join(" "),
    getDocumentRequiredFor(document).join(" "),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (document.category === "permit" || searchable.includes("permit")) {
    return "permit";
  }

  if (document.category === "material_order" || searchable.includes("material order")) {
    return "material_order";
  }

  if (searchable.includes("insurance") || searchable.includes("hoa")) {
    return "insurance";
  }

  if (
    document.category === "insurance" ||
    searchable.includes("insurance") ||
    searchable.includes("hoa")
  ) {
    return "insurance";
  }

  if (
    document.category === "photo" ||
    document.category === "photo_set" ||
    searchable.includes("photo set")
  ) {
    return "photo_set";
  }

  if (document.category === "manufacturer_warranty") {
    return "manufacturer_warranty";
  }

  if (document.category === "workmanship_warranty") {
    return "workmanship_warranty";
  }

  if (
    related.inspection &&
    (searchable.includes("roof report") ||
      searchable.includes("roof inspection") ||
      related.inspection.inspection_type === "roof_inspection")
  ) {
    return "roof_report";
  }

  if (
    document.category === "inspection_report" ||
    related.inspection ||
    searchable.includes("inspection")
  ) {
    return "inspection_report";
  }

  if (
    document.category === "estimate" &&
    (document.status === "signed" ||
      signatures.some((signature) => signature.status === "signed") ||
      searchable.includes("signed proposal"))
  ) {
    return "signed_proposal";
  }

  if (document.category === "estimate" || searchable.includes("proposal")) {
    return "proposal";
  }

  if (document.category === "contract" || document.category === "signed_agreement") {
    return "contract";
  }

  if (document.category === "change_order") {
    return "change_order";
  }

  if (document.category === "invoice") {
    return "invoice";
  }

  if (document.category === "warranty") {
    return "warranty";
  }

  return "other";
}

function documentLibraryCategoryLabel(category: DocumentLibraryCategory) {
  return (
    documentLibraryCategories.find((item) => item.value === category)?.label ?? "Other"
  );
}

function getDocumentLibraryDetails(
  snapshot: CrmSnapshot,
  document: DocumentRecord,
): DocumentLibraryDetails {
  const association = getDocumentAssociationSummary(snapshot, document);
  const related = getDocumentRelatedRecords(snapshot, document);
  const signatures = snapshot.signatures.filter(
    (signature) => signature.document_id === document.id,
  );
  const libraryCategory = getDocumentLibraryCategory(document, related, signatures);
  const relationTypes = uniqueDocumentStrings([
    related.customer ? "customer" : null,
    related.lead ? "lead" : null,
    getLeadIsOpportunity(related.lead) || document.template_key?.includes("opportunity")
      ? "opportunity"
      : null,
    related.estimate ? "estimate" : null,
    related.job ? "job" : null,
    related.inspection ? "inspection" : null,
    related.invoice ? "invoice" : null,
    related.changeOrder ? "change_order" : null,
  ]) as DocumentRelationFilter[];
  const uploadStatus = document.storage_path
    ? "Stored file"
    : document.file_url
      ? "Linked file"
      : document.body
      ? "PDF-ready draft"
      : "Needs content";
  const uploadTone: "blue" | "green" | "amber" = document.file_url
    ? "green"
    : document.storage_path
      ? "green"
    : document.body
      ? "blue"
      : "amber";
  const previewMode = document.storage_path
    ? "Private file"
    : document.file_url
      ? "File link"
      : document.body
      ? "Text preview"
      : "Metadata only";
  const tags = uniqueDocumentStrings([
    ...getDocumentTags(document),
    documentLibraryCategoryLabel(libraryCategory),
    documentStatusLabel(document.status),
    getDocumentRequirementLevel(document) === "required" ? "Required" : "Optional",
    ...getDocumentRequiredFor(document),
    document.file_name,
    document.file_size_bytes ? formatFileSize(document.file_size_bytes) : null,
    companyMapSafeName(snapshot, document.company_id),
    related.customer?.status,
    related.job?.status,
    related.estimate?.status,
    related.invoice?.status,
    related.inspection?.status,
    related.lead?.source,
    related.lead?.pipeline_stage?.replace(/_/g, " "),
    document.template_key?.replace(/_/g, " "),
    document.storage_path ? "Stored file" : document.file_url ? "File linked" : "Generated",
  ]);
  const activityItems: Array<DocumentActivityItem | null> = [
    {
      id: "created",
      label: "Document created",
      detail: `${documentLibraryCategoryLabel(libraryCategory)} linked to ${association.source}`,
      occurredAt: document.created_at,
    },
    {
      id: "updated",
      label: "Document updated",
      detail: `${documentStatusLabel(document.status)} · ${uploadStatus}`,
      occurredAt: document.updated_at,
    },
    ...signatures.map((signature) => ({
      id: `signature-${signature.id}`,
      label:
        signature.status === "signed"
          ? "Signature completed"
          : signature.status === "viewed"
            ? "Signature viewed"
            : signature.status === "declined"
              ? "Signature declined"
              : signature.status === "expired"
                ? "Signature expired"
                : "Signature requested",
      detail: `${getElectronicSignatureProviderLabel(signature.provider)} - ${signature.signer_name}`,
      occurredAt: signature.signed_at ?? signature.updated_at,
    })),
    related.inspection
      ? {
          id: `inspection-${related.inspection.id}`,
          label: "Inspection relationship",
          detail: `${related.inspection.title} · ${inspectionStatusLabel(related.inspection.status)}`,
          occurredAt: related.inspection.updated_at,
        }
      : null,
  ];
  const activity = activityItems.filter(
    (item): item is DocumentActivityItem => item !== null,
  );

  return {
    association,
    libraryCategory,
    relationTypes,
    tags,
    uploadStatus,
    uploadTone,
    previewMode,
    relatedCustomer: related.customer,
    relatedLead: related.lead,
    relatedEstimate: related.estimate,
    relatedJob: related.job,
    relatedInspection: related.inspection,
    relatedInvoice: related.invoice,
    relatedChangeOrder: related.changeOrder,
    signatures,
    activity: activity.sort((a, b) =>
      (b.occurredAt ?? "").localeCompare(a.occurredAt ?? ""),
    ),
  };
}

function companyMapSafeName(snapshot: CrmSnapshot, companyId: string) {
  return snapshot.companies.find((company) => company.id === companyId)?.name ?? null;
}

function buildDocumentReadinessWarnings(snapshot: CrmSnapshot) {
  const estimateWarnings = snapshot.estimates
    .filter(
      (estimate) =>
        (estimate.status === "sent" || estimate.status === "approved") &&
        !snapshot.documents.some((document) => document.estimate_id === estimate.id),
    )
    .map((estimate) => ({
      id: `estimate-${estimate.id}`,
      companyId: estimate.company_id,
      title: "Proposal document missing",
      detail: `${estimate.title} is ${estimate.status.replace("_", " ")} without a saved proposal packet.`,
      action: "Open estimate",
    }));
  const invoiceWarnings = snapshot.invoices
    .filter(
      (invoice) =>
        invoice.status !== "draft" &&
        !snapshot.documents.some((document) => document.invoice_id === invoice.id),
    )
    .map((invoice) => ({
      id: `invoice-${invoice.id}`,
      companyId: invoice.company_id,
      title: "Invoice document missing",
      detail: `${invoice.invoice_number} is ${invoice.status} without a saved invoice packet.`,
      action: "Open invoice",
    }));
  const completionWarnings = snapshot.jobs
    .filter(
      (job) =>
        job.status === "completed" &&
        !snapshot.documents.some(
          (document) =>
            document.job_id === job.id && document.category === "completion_certificate",
        ),
    )
    .map((job) => ({
      id: `completion-${job.id}`,
      companyId: job.company_id,
      title: "Completion certificate missing",
      detail: `${job.title} is completed without a completion certificate.`,
      action: "Open job",
    }));
  const warrantyWarnings = snapshot.jobs
    .filter(
      (job) =>
        job.status === "completed" &&
        !snapshot.documents.some(
          (document) =>
            document.job_id === job.id &&
            (document.category === "warranty" ||
              document.category === "manufacturer_warranty" ||
              document.category === "workmanship_warranty"),
        ),
    )
    .map((job) => ({
      id: `warranty-${job.id}`,
      companyId: job.company_id,
      title: "Warranty document missing",
      detail: `${job.title} is completed without a warranty packet.`,
      action: "Open job",
    }));
  const inspectionWarnings = snapshot.inspections
    .filter(
      (inspection) =>
        inspection.report_requested &&
        !inspection.report_document_id &&
        inspection.status !== "canceled",
    )
    .map((inspection) => ({
      id: `inspection-${inspection.id}`,
      companyId: inspection.company_id,
      title: "Inspection report requested",
      detail: `${inspection.title} needs a saved inspection report document.`,
      action: "Open inspection",
    }));
  const jobStartWarnings = snapshot.jobs
    .filter(
      (job) =>
        (job.status === "scheduled" || job.status === "in_progress") &&
        (!snapshot.documents.some(
          (document) => document.job_id === job.id && document.category === "permit",
        ) ||
          !snapshot.documents.some(
            (document) =>
              document.job_id === job.id && document.category === "material_order",
          )),
    )
    .map((job) => ({
      id: `job-start-${job.id}`,
      companyId: job.company_id,
      title: "Job start packet incomplete",
      detail: `${job.title} should have permit and material order documents before production starts.`,
      action: "Open job",
    }));
  const requiredMetadataWarnings = snapshot.documents
    .filter(
      (document) =>
        getDocumentRequirementLevel(document) === "required" &&
        !hasDocumentFile(document) &&
        !document.body &&
        document.status !== "archived",
    )
    .map((document) => ({
      id: `required-document-${document.id}`,
      companyId: document.company_id,
      title: "Required document missing content",
      detail: `${document.title} is marked required without a stored file, link, or draft body.`,
      action: "Open document",
    }));

  return [
    ...estimateWarnings,
    ...invoiceWarnings,
    ...completionWarnings,
    ...warrantyWarnings,
    ...inspectionWarnings,
    ...jobStartWarnings,
    ...requiredMetadataWarnings,
  ];
}

function documentStatusTone(status: DocumentStatus) {
  if (status === "signed") {
    return "green";
  }

  if (status === "ready" || status === "sent") {
    return "blue";
  }

  return "amber";
}

function getSignatureTargetName(snapshot: CrmSnapshot, signature: SignatureRecord) {
  return (
    snapshot.documents.find((document) => document.id === signature.document_id)?.title ??
    snapshot.changeOrders.find(
      (changeOrder) => changeOrder.id === signature.change_order_id,
    )?.title ??
    getCustomerName(snapshot, signature.customer_id) ??
    getEmployeeName(snapshot, signature.employee_id) ??
    "Signature"
  );
}

function getPaymentTargetName(snapshot: CrmSnapshot, payment: PaymentRecord) {
  return (
    snapshot.invoices.find((invoice) => invoice.id === payment.invoice_id)
      ?.invoice_number ??
    getCustomerName(snapshot, payment.customer_id) ??
    "Payment"
  );
}

function getAssociationSummary(
  snapshot: CrmSnapshot,
  {
    customerId,
    leadId,
    estimateId,
  }: {
    customerId?: string | null;
    leadId?: string | null;
    estimateId?: string | null;
  },
) {
  const estimate = estimateId
    ? snapshot.estimates.find((item) => item.id === estimateId)
    : null;
  const customer =
    (customerId
      ? snapshot.customers.find((item) => item.id === customerId)
      : null) ??
    (estimate?.customer_id
      ? snapshot.customers.find((item) => item.id === estimate.customer_id)
      : null);
  const lead =
    (leadId ? snapshot.leads.find((item) => item.id === leadId) : null) ??
    (estimate?.lead_id
      ? snapshot.leads.find((item) => item.id === estimate.lead_id)
      : null);
  const addressParts = customer
    ? [
        customer.property_address,
        customer.city,
        customer.state,
        customer.postal_code,
      ]
    : lead
      ? [lead.property_address, lead.city, lead.state, lead.postal_code]
      : [];
  const address = addressParts.filter(Boolean).join(", ");

  return {
    name: customer?.display_name ?? lead?.contact_name ?? "Unassigned",
    contact: customer?.contact_name ?? lead?.contact_name ?? "No contact",
    phone: customer?.phone ?? lead?.phone ?? "No phone",
    email: customer?.email ?? lead?.email ?? "No email",
    address: address || "No property linked",
    source: customer ? "Customer" : lead ? "Lead" : estimate ? "Estimate" : "Unassigned",
  };
}

function getSmsTargetName(snapshot: CrmSnapshot, message: SmsMessageRecord) {
  return (
    getCustomerName(snapshot, message.customer_id) ??
    getLeadName(snapshot, message.lead_id) ??
    getJobName(snapshot, message.job_id) ??
    snapshot.scheduleEvents.find((event) => event.id === message.schedule_event_id)
      ?.title ??
    snapshot.invoices.find((invoice) => invoice.id === message.invoice_id)
      ?.invoice_number ??
    "General SMS"
  );
}

function getCaughtErrorMessage(currentError: unknown, fallback: string) {
  if (currentError instanceof Error) {
    return currentError.message;
  }

  if (typeof currentError === "string") {
    return currentError;
  }

  if (currentError && typeof currentError === "object" && "message" in currentError) {
    const message = (currentError as { message?: unknown }).message;

    if (typeof message === "string") {
      return message;
    }
  }

  return fallback;
}

function logCaughtError(label: string, currentError: unknown) {
  console.error(label, {
    error: currentError,
    message: getCaughtErrorMessage(currentError, "Unknown error."),
    stack: currentError instanceof Error ? currentError.stack : undefined,
    cause:
      currentError instanceof Error
        ? (currentError as Error & { cause?: unknown }).cause
        : undefined,
  });
}

async function withTimeout<Result>(
  promise: Promise<Result>,
  timeoutMs: number,
  message: string,
) {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  try {
    return await Promise.race([
      promise,
      new Promise<Result>((_resolve, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), timeoutMs);
      }),
    ]);
  } finally {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
  }
}

export function CrmApp() {
  const demoFallbackEnabled = isCrmDemoFallbackEnabled();
  const demoUser = useMemo(
    () =>
      ({
        id: "local-demo-user",
        email: "local@weathertech.demo",
      }) as User,
    [],
  );

  const [initialWorkspaceLocation] = useState(readWorkspaceLocation);
  const [client] = useState<SupabaseClient<Database> | null>(() =>
    getSupabaseBrowserClient(),
  );
  const [user, setUser] = useState<User | null>(null);
  const [authReady, setAuthReady] = useState(client === null);
  const [snapshot, setSnapshot] = useState<CrmSnapshot | null>(null);
  const [aiProviderStatusRefreshSequence, setAiProviderStatusRefreshSequence] =
    useState(0);
  const [view, setView] = useState<WorkspaceView>(initialWorkspaceLocation.view);
  const [workspaceRecordFocus, setWorkspaceRecordFocus] =
    useState<WorkspaceRecordFocus | null>(initialWorkspaceLocation.focus);
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [snapshotTransitionPending, setSnapshotTransitionPending] = useState(false);
  const snapshotLoadRequestSequenceRef = useRef(0);
  const snapshotTransitionPendingRef = useRef(false);
  const [theme, setTheme] = useState<ThemeMode>(() => {
    if (typeof window === "undefined") {
      return "light";
    }

    return window.localStorage.getItem("weathertech-theme") === "dark"
      ? "dark"
      : "light";
  });

  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    window.localStorage.setItem("weathertech-theme", theme);
  }, [theme]);

  useEffect(() => {
    const handleHistoryNavigation = () => {
      const location = readWorkspaceLocation();
      setView(location.view);
      setWorkspaceRecordFocus(location.focus);
      setNotice("");
      setError("");
    };

    window.addEventListener("popstate", handleHistoryNavigation);
    return () => window.removeEventListener("popstate", handleHistoryNavigation);
  }, []);

  const handleThemeChange = (nextTheme: ThemeMode) => {
    setTheme(nextTheme);
  };

  const beginSnapshotTransition = useCallback(() => {
    const requestSequence = snapshotLoadRequestSequenceRef.current + 1;
    snapshotLoadRequestSequenceRef.current = requestSequence;
    snapshotTransitionPendingRef.current = true;
    setSnapshotTransitionPending(true);
    setAiProviderStatusRefreshSequence((current) => current + 1);
    return requestSequence;
  }, []);

  const completeSnapshotTransition = useCallback((requestSequence: number) => {
    if (snapshotLoadRequestSequenceRef.current !== requestSequence) {
      return false;
    }
    snapshotTransitionPendingRef.current = false;
    setSnapshotTransitionPending(false);
    return true;
  }, []);

  const applyImmediateSnapshotTransition = useCallback(
    (transition: () => void) => {
      const requestSequence = beginSnapshotTransition();
      try {
        transition();
      } finally {
        completeSnapshotTransition(requestSequence);
      }
    },
    [beginSnapshotTransition, completeSnapshotTransition],
  );

  const isSnapshotContextCurrent = useCallback(
    (requestSequence: number) =>
      !snapshotTransitionPendingRef.current &&
      snapshotLoadRequestSequenceRef.current === requestSequence,
    [],
  );

  const loadSnapshot = useCallback(async (crmClient: CrmClient, showLoading = true) => {
    const requestSequence = beginSnapshotTransition();
    if (showLoading) {
      setIsLoading(true);
    }
    setError("");

    try {
      const nextSnapshot = await fetchCrmSnapshot(crmClient);
      if (snapshotLoadRequestSequenceRef.current !== requestSequence) {
        return;
      }
      setSnapshot(nextSnapshot);
    } catch (currentError) {
      if (snapshotLoadRequestSequenceRef.current !== requestSequence) {
        return;
      }
      logCaughtError("[CRM] CRM snapshot load failed", currentError);

      if (demoFallbackEnabled) {
        setSnapshot(createDemoCrmSnapshot());
        setNotice("Using local demo CRM data because live Supabase CRM is unavailable.");
        return;
      }

      setError(getCaughtErrorMessage(currentError, "Unable to load CRM records."));
    } finally {
      if (completeSnapshotTransition(requestSequence)) {
        setIsLoading(false);
      }
    }
  }, [beginSnapshotTransition, completeSnapshotTransition, demoFallbackEnabled]);

  useEffect(() => {
    if (!client) {
      if (demoFallbackEnabled) {
        applyImmediateSnapshotTransition(() => {
          setUser(demoUser);
          setSnapshot(createDemoCrmSnapshot());
          setAuthReady(true);
          setIsLoading(false);
          setNotice("Using local demo CRM data because Supabase is not configured.");
        });
      }

      return;
    }

    let isMounted = true;

    withTimeout(
      client.auth.getSession(),
      8000,
      "Supabase session check timed out.",
    )
      .then(({ data }) => {
        if (!isMounted) {
          return;
        }

        const activeUser = data.session?.user ?? null;

        if (activeUser) {
          setUser(activeUser);
          setAuthReady(true);
          void loadSnapshot(client);
        } else if (demoFallbackEnabled) {
          applyImmediateSnapshotTransition(() => {
            setUser(demoUser);
            setSnapshot(createDemoCrmSnapshot());
            setAuthReady(true);
            setIsLoading(false);
            setNotice("Using local demo CRM data because Supabase sign-in is not ready.");
          });
        } else {
          applyImmediateSnapshotTransition(() => {
            setUser(null);
            setSnapshot(null);
            setAuthReady(true);
            setIsLoading(false);
          });
        }
      })
      .catch((sessionError) => {
        console.error("Supabase session check failed:", sessionError);

        if (!isMounted) {
          return;
        }

        if (demoFallbackEnabled) {
          applyImmediateSnapshotTransition(() => {
            setUser(demoUser);
            setSnapshot(createDemoCrmSnapshot());
            setAuthReady(true);
            setIsLoading(false);
            setNotice("Using local demo CRM data because Supabase auth failed to load.");
          });
        } else {
          setError(
            sessionError instanceof Error
              ? sessionError.message
              : "Unable to load Supabase session.",
          );
          setAuthReady(true);
          setIsLoading(false);
        }
      });

    const { data: listener } = client.auth.onAuthStateChange((_event, session) => {
      const activeUser = session?.user ?? null;

      if (activeUser) {
        setUser(activeUser);
        setAuthReady(true);
        void loadSnapshot(client);
      } else if (demoFallbackEnabled) {
        applyImmediateSnapshotTransition(() => {
          setUser(demoUser);
          setSnapshot(createDemoCrmSnapshot());
          setAuthReady(true);
          setIsLoading(false);
        });
      } else {
        applyImmediateSnapshotTransition(() => {
          setUser(null);
          setSnapshot(null);
          setAuthReady(true);
          setIsLoading(false);
        });
      }
    });

    return () => {
      isMounted = false;
      listener.subscription.unsubscribe();
    };
  }, [applyImmediateSnapshotTransition, client, demoFallbackEnabled, demoUser, loadSnapshot]);

  const handleAuthNotice = (message: string) => {
    setNotice(message);
    setError("");
  };

  const handleWorkspaceNotice = useCallback((message: string) => {
    setNotice((currentNotice) => (currentNotice === message ? currentNotice : message));
    setError("");
  }, []);

  const handleWorkspaceError = useCallback((message: string) => {
    setError((currentError) => (currentError === message ? currentError : message));
    setNotice("");
  }, []);

  const handleWorkspaceViewChange = useCallback<WorkspaceViewChange>((nextView, focus = null) => {
    setView(nextView);
    setWorkspaceRecordFocus(focus);
    writeWorkspaceLocation(nextView, focus);
    setNotice("");
    setError("");
  }, []);

  const handleSignOut = async () => {
    if (!client) {
      return;
    }

    await client.auth.signOut();
    setNotice("Signed out.");
    setView("dashboard");
    setWorkspaceRecordFocus(null);
    writeWorkspaceLocation("dashboard", null, "replace");
  };

  const handleDemoSnapshotChange = useCallback(
    (updater: (currentSnapshot: CrmSnapshot) => CrmSnapshot) => {
      applyImmediateSnapshotTransition(() => {
        setSnapshot((currentSnapshot) =>
          currentSnapshot
            ? projectDemoAccountabilityMilestones(
                currentSnapshot,
                updater(currentSnapshot),
              )
            : currentSnapshot,
        );
      });
    },
    [applyImmediateSnapshotTransition],
  );

  if (!authReady) {
    return <LoadingScreen label="Preparing WeatherTech OS" />;
  }

  if (!client && !demoFallbackEnabled) {
    return <SupabaseConfigScreen />;
  }

  if (!user) {
    if (!client) {
      return <LoadingScreen label="Loading local demo workspace" />;
    }

    return (
      <AuthScreen client={client} notice={notice} onNotice={handleAuthNotice} />
    );
  }

  if (error && !snapshot && !isLoading) {
    return (
      <LoadErrorScreen
        message={error}
        onRetry={() => {
          if (client) {
            void loadSnapshot(client);
          } else {
            applyImmediateSnapshotTransition(() => {
              setSnapshot(createDemoCrmSnapshot());
            });
          }
        }}
        onSignOut={handleSignOut}
      />
    );
  }

  if (!snapshot || isLoading) {
    return <LoadingScreen label="Loading CRM workspace" />;
  }

  const isDemoWorkspace = demoFallbackEnabled && user.id === demoUser.id;

  return (
    <CrmWorkspace
      client={client ?? ({} as CrmClient)}
      isDemoMode={isDemoWorkspace}
      notice={notice}
      error={error}
      snapshot={snapshot}
      user={user}
      view={view}
      workspaceRecordFocus={workspaceRecordFocus}
      aiProviderStatusRefreshSequence={aiProviderStatusRefreshSequence}
      snapshotTransitionPending={snapshotTransitionPending}
      isSnapshotContextCurrent={isSnapshotContextCurrent}
      theme={theme}
      onViewChange={handleWorkspaceViewChange}
      onThemeChange={handleThemeChange}
      onReload={async () => {
        if (client && !isDemoWorkspace) {
          await loadSnapshot(client);
        } else {
          applyImmediateSnapshotTransition(() => {
            setSnapshot(createDemoCrmSnapshot());
          });
        }
      }}
      onScrollPreservingReload={async () => {
        const scrollLeft = window.scrollX;
        const scrollTop = window.scrollY;

        try {
          if (client && !isDemoWorkspace) {
            await loadSnapshot(client, false);
          } else {
            applyImmediateSnapshotTransition(() => {
              setSnapshot(createDemoCrmSnapshot());
            });
          }
        } finally {
          restoreWindowScrollPosition(scrollLeft, scrollTop);
        }
      }}
      onDemoSnapshotChange={handleDemoSnapshotChange}
      onSignOut={handleSignOut}
      onNotice={handleWorkspaceNotice}
      onError={handleWorkspaceError}
    />
  );
}

