function ToastViewport({
  notice,
  error,
  onDismissNotice,
  onDismissError,
}: {
  notice: string;
  error: string;
  onDismissNotice: () => void;
  onDismissError: () => void;
}) {
  if (!notice && !error) {
    return null;
  }

  return (
    <div
      aria-live="polite"
      className="pointer-events-none fixed inset-x-3 top-3 z-50 grid justify-items-end gap-2 sm:inset-x-auto sm:right-5 sm:top-5 sm:w-[min(24rem,calc(100vw-2rem))]"
    >
      {notice ? (
        <Toast tone="success" message={notice} onDismiss={onDismissNotice} />
      ) : null}
      {error ? <Toast tone="error" message={error} onDismiss={onDismissError} /> : null}
    </div>
  );
}

function Toast({
  tone,
  message,
  onDismiss,
}: {
  tone: "success" | "error";
  message: string;
  onDismiss: () => void;
}) {
  return (
    <div
      role={tone === "error" ? "alert" : "status"}
      aria-label={tone === "success" ? "Success notification" : "Error notification"}
      className={`pointer-events-auto w-full rounded-lg border px-4 py-3 text-sm font-semibold shadow-xl backdrop-blur ${
        tone === "success"
          ? "border-emerald-200 bg-emerald-50/95 text-emerald-800"
          : "border-red-200 bg-red-50/95 text-red-800"
      }`}
    >
      <div className="flex items-start gap-3">
        {tone === "success" ? (
          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
        ) : (
          <ShieldCheck className="mt-0.5 h-4 w-4 shrink-0" />
        )}
        <span className="min-w-0 flex-1 pr-1">{message}</span>
        <button
          type="button"
          onClick={onDismiss}
          aria-label={`Dismiss ${tone === "success" ? "success" : "error"} notification`}
          className="rounded-md p-1 transition hover:bg-black/5 focus:outline-none focus:ring-2 focus:ring-current focus:ring-offset-2 focus:ring-offset-white"
        >
          <X className="h-4 w-4" aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}

function Badge({ label, tone }: { label: string; tone: "blue" | "green" | "amber" }) {
  const toneClass = {
    amber: "bg-amber-100 text-amber-800",
    blue: "bg-sky-100 text-sky-800",
    green: "bg-emerald-100 text-emerald-800",
  }[tone];
  const readableLabel = label.replace(/_/g, " ");

  return (
    <span
      aria-label={readableLabel}
      className={`wt-status-badge wt-status-badge-${tone} inline-flex w-fit rounded-md px-2.5 py-1 text-xs font-bold capitalize leading-none tracking-wide ${toneClass}`}
    >
      {readableLabel}
    </span>
  );
}

function Message({ tone, message }: { tone: "success" | "error"; message: string }) {
  return (
    <div
      className={`mt-4 rounded-md border px-4 py-3 text-sm font-medium ${
        tone === "success"
          ? "border-emerald-200 bg-emerald-50 text-emerald-800"
          : "border-red-200 bg-red-50 text-red-800"
      }`}
    >
      {message}
    </div>
  );
}

function EmptyState({
  label,
  description,
}: {
  label: string;
  description?: string;
}) {
  return (
    <div
      role="status"
      className="wt-empty-state grid place-items-center rounded-lg border border-dashed border-slate-300 bg-slate-50 p-8 text-center"
    >
      <div className="max-w-md">
        <div className="mx-auto grid h-11 w-11 place-items-center rounded-md bg-sky-100 text-sky-700">
          <Search className="h-5 w-5" />
        </div>
        <p className="mt-3 text-sm font-bold text-slate-700">{label}</p>
        <p className="mt-1 text-sm text-slate-500">
          {description ??
            "When records match this workspace, they will appear here with the next action available."}
        </p>
      </div>
    </div>
  );
}

function PaginationControls({
  page,
  pageCount,
  total,
  onPageChange,
}: {
  page: number;
  pageCount: number;
  total: number;
  onPageChange: (page: number) => void;
}) {
  if (pageCount <= 1) {
    return null;
  }

  return (
    <nav
      aria-label="Pagination"
      className="flex flex-col gap-3 border-t border-slate-200 px-5 py-4 text-sm sm:flex-row sm:items-center sm:justify-between"
    >
      <span className="font-medium text-slate-500">
        Page {page} of {pageCount} - {total} records
      </span>
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => onPageChange(Math.max(page - 1, 1))}
          disabled={page === 1}
          aria-label={`Go to page ${Math.max(page - 1, 1)}`}
          className="wt-control-button wt-control-button-secondary border border-slate-300 px-3 py-2 font-semibold text-slate-700 hover:bg-slate-50"
        >
          Previous
        </button>
        <button
          type="button"
          onClick={() => onPageChange(Math.min(page + 1, pageCount))}
          disabled={page === pageCount}
          aria-label={`Go to page ${Math.min(page + 1, pageCount)}`}
          className="wt-control-button wt-control-button-secondary border border-slate-300 px-3 py-2 font-semibold text-slate-700 hover:bg-slate-50"
        >
          Next
        </button>
      </div>
    </nav>
  );
}

function usePagination<T>(items: T[], pageSize = 8) {
  const [page, setPage] = useState(1);
  const pageCount = Math.max(Math.ceil(items.length / pageSize), 1);
  const effectivePage = Math.min(page, pageCount);

  return {
    page: effectivePage,
    pageCount,
    setPage,
    pagedItems: items.slice((effectivePage - 1) * pageSize, effectivePage * pageSize),
  };
}
